  task automatic bp06();
    int              dst, sl, k, n_cx, n_ok, n_bad, npk, blen, L, nxt, si;
    bit              mode, ok, in_t, exp_cx;
    int unsigned     r0, t_end, t_inj, t_lo, t_hi;
    longint unsigned n_c;
    int unsigned     tt [NN];
    bit              done [NN];
    longint unsigned c1 [NN], l1 [NN], rc1, tk1, ok1;
    traffic_pkg::dlog_t d;
    dst  = NN - 1;
    npk  = B_MAX / MAX_PKT_FLITS;
    if (npk > NUM_VC) npk = NUM_VC;
    if (npk < 1)      npk = 1;
    blen = npk * MAX_PKT_FLITS;
    exp_cx = (NN - 2) * blen + B_MAX > SPACE;
    tb_pkg::phase($sformatf("BP06 cancellation: R%0d's sink stalled for a round while every other node holds %0d packets for it", dst, npk));
    traffic_defaults();
    traffic_pkg::dlog.delete();
    traffic_pkg::log_on = 1'b1;
    r0 = round_start(cyc + 200);
    for (int s = 0; s < NN; s++) begin
      tt[s]   = 0;
      done[s] = (s == dst);
      if (s == dst) continue;
      ok    = find_sub(s, dst, sl, k, mode);
      `TB_CHECK(ok, ("BP06: the timetable never lets R%0d send to R%0d", s, dst))
      tt[s] = sub_start(sl, k, r0);
    end
    t_end = r0 + BRL + 2 * sched_pkg::hmax(MESH_N) + B_MAX + 4;
    at_cycle(r0 - 120);
    traffic_pkg::fs_node  = dst;
    traffic_pkg::fs_start = r0 - 100;
    traffic_pkg::fs_end   = t_end;
    for (int s = 0; s < NN; s++) if (s != dst) hold_req[s] = 5'b10000;
    snap6_at = r0;
    for (int i = 0; i < NN - 1; i++) begin
      nxt = -1;
      for (int s = 0; s < NN; s++) if (!done[s] && (nxt < 0 || tt[s] < tt[nxt])) nxt = s;
      done[nxt] = 1'b1;
      t_inj = tt[nxt] - BYP_LEAD;
      at_cycle(t_inj);
      for (int m = 0; m < npk; m++) traffic_pkg::direct(nxt, dst, MAX_PKT_FLITS);
    end
    in_cycle(r0 + BRL);
    for (int s = 0; s < NN; s++) begin
      c1[s] = v_cxl[s];
      l1[s] = v_lost[s];
    end
    rc1 = v_rcx[dst];
    tk1 = (rchk_pkg::the_chk == null) ? 0 : rchk_pkg::the_chk.n_tok;
    ok1 = (rchk_pkg::the_chk == null) ? 0 : rchk_pkg::the_chk.n_cxok;
    snap6_at = 0;
    at_cycle(t_end);
    for (int s = 0; s < NN; s++) hold_req[s] = '0;
    wait_delivered("BP06");
    n_cx  = 0;
    n_bad = 0;
    for (int s = 0; s < NN; s++) begin
      if (s == dst) continue;
      if (c1[s] != s6_cxl[s]) begin
        n_cx++;
        if (c1[s] - s6_cxl[s] != 1 || l1[s] - s6_lost[s] != 1) begin
          n_bad++;
          tb_pkg::info($sformatf("BP06: R%0d: %0d turns cancelled, %0d of them with a packet waiting; its turn to R%0d at cycle %0d",
                                 s, c1[s] - s6_cxl[s], l1[s] - s6_lost[s], dst, tt[s]));
        end
      end
    end
    if (exp_cx) begin
      `TB_CHECK(n_cx >= 1, ("BP06: R%0d's sink was stalled for a round and no turn was cancelled", dst))
    end else begin
      tb_pkg::info($sformatf("BP06: %0d bursts of %0d flits fit in R%0d's bypass space of %0d flits, so no cancel is certain here",
                             NN - 1, blen, dst, SPACE));
    end
    `TB_CHECK(n_bad == 0, ("BP06: %0d cancelled sources did not skip exactly one turn with their packets waiting", n_bad))
    `TB_CHECK(longint'(n_cx) == rc1 - s6_rcx,
              ("BP06: R%0d's NI cancelled %0d turns, %0d sources skipped one", dst, rc1 - s6_rcx, n_cx))
    if (rchk_pkg::the_chk != null) begin
      `TB_CHECK(ok1 - s6_ok == longint'(n_cx),
                ("BP06: the checker saw %0d cancelled turns with nothing sent, expected %0d", ok1 - s6_ok, n_cx))
    end
    n_ok = 0;
    foreach (traffic_pkg::dlog[i]) begin
      d    = traffic_pkg::dlog[i];
      si   = int'(d.src);
      L    = nhops(si, dst);
      t_lo = tt[si] + sched_pkg::tc_eject(L, MAX_PKT_FLITS - 1);
      t_hi = tt[si] + sched_pkg::tc_eject(L, blen - 1);
      in_t = d.byp && d.t_tail >= t_lo && d.t_tail <= t_hi;
      n_c  = c1[si] - s6_cxl[si];
      if ((n_c != 0) != in_t) n_ok++;
      else tb_pkg::info($sformatf("BP06: packet %0d.%0d from R%0d: bypass %0b, tail at %0d, its turn at %0d, the source's turns cancelled %0d",
                                  d.src, d.seq, d.src, d.byp, d.t_tail, tt[si], n_c));
    end
    `TB_CHECK(traffic_pkg::dlog.size() == (NN - 1) * npk && n_ok == (NN - 1) * npk,
              ("BP06: %0d packets delivered, %0d as expected (accepted ones by bypass in the turn, cancelled ones later); expected %0d",
               traffic_pkg::dlog.size(), n_ok, (NN - 1) * npk))
    tb_pkg::info($sformatf("BP06: %0d of %0d turns to R%0d accepted while its sink was stalled, then %0d cancelled (its bypass space peaked at %0d of %0d flits); the checker matched %0d cancel tokens on their links; every cancelled source skipped its turn and its packets arrived after the stall",
                           NN - 1 - n_cx, NN - 1, dst, n_cx, v_msum[dst], SPACE, tk1 - s6_tok));
    if (exp_cx) tb_pkg::cover_bin("BP06 turns cancelled", longint'(n_cx));
    else        tb_pkg::cover_goal("BP06 turns cancelled", longint'(n_cx));
    traffic_pkg::log_on = 1'b0;
    check_idle("BP06");
    traffic_defaults();
  endtask

  task automatic bp07();
    int              dst, src, sl, k, bad, blen, nmax;
    bit              mode, ok;
    int unsigned     r0, t, t_end;
    longint unsigned d0, a0, x0, n0, c0;
    tb_pkg::phase("BP07 release: an idle round, then a long sink stall with bursts and regular packets coming");
    traffic_defaults();
    r0 = round_start(cyc + 10);
    in_cycle(r0);
    d0 = sum_of(v_dec);
    a0 = sum_of(v_acc);
    x0 = sum_of(v_rcx);
    n0 = sum_of(v_nosh);
    bad = 0;
    for (int s = 0; s < BNS; s++) begin
      in_cycle(r0 + s * BSL);              // a slot's first setup cycle, before its decisions
      if (sum_res() != 0) bad++;
    end
    in_cycle(r0 + BRL);
    if (sum_res() != 0) bad++;
    `TB_CHECK(bad == 0, ("BP07 a: reservations still held at %0d of %0d slot boundaries", bad, BNS + 1))
    `TB_CHECK(sum_of(v_dec) - d0 == longint'(NPAIRS) && sum_of(v_acc) - a0 == sum_of(v_dec) - d0 &&
              sum_of(v_rcx) - x0 == 0 && sum_of(v_nosh) - n0 == sum_of(v_acc) - a0,
              ("BP07 a: one idle round: %0d decisions (expected %0d), %0d accepted, %0d cancelled, %0d released as no-shows",
               sum_of(v_dec) - d0, NPAIRS, sum_of(v_acc) - a0, sum_of(v_rcx) - x0, sum_of(v_nosh) - n0))
    tb_pkg::info($sformatf("BP07 a: one idle round: %0d decisions, all accepted, all released as no-shows; no reservation held at any of the %0d slot boundaries",
                           sum_of(v_dec) - d0, BNS + 1));
    dst = NN - 1;
    traffic_pkg::dlog.delete();
    traffic_pkg::log_on = 1'b1;
    r0 = round_start(cyc + 200);
    c0 = v_rcx[dst];
    t_end = r0 + BRL + 2 * sched_pkg::hmax(MESH_N) + B_MAX + 4;
    at_cycle(r0 - 120);
    traffic_pkg::fs_node  = dst;
    traffic_pkg::fs_start = r0 - 110;
    traffic_pkg::fs_end   = t_end + 200;
    for (int s = 0; s < NN; s++) begin
      if (s == dst) continue;
      hold_req[s] = 5'b10000;
      traffic_pkg::direct(s, dst, MAX_PKT_FLITS);
    end
    at_cycle(r0 - 100);
    hold_req[dst - 1]      = '0;
    hold_req[dst - MESH_N] = '0;
    for (int i = 0; i < 2 * NUM_VC; i++) begin
      traffic_pkg::direct(dst - 1, dst, MAX_PKT_FLITS);
      traffic_pkg::direct(dst - MESH_N, dst, MAX_PKT_FLITS);
    end
    at_cycle(t_end);
    for (int s = 0; s < NN; s++) hold_req[s] = '0;
    nmax = (nchk_pkg::the_nchk == null) ? 0 : nchk_pkg::the_nchk.max_occ;
    wait_delivered("BP07 b");
    `TB_CHECK(v_rcx[dst] - c0 >= 1, ("BP07 b: R%0d's sink was stalled for a round and its NI cancelled nothing", dst))
    tb_pkg::info($sformatf("BP07 b: R%0d stalled for %0d cycles: its NI cancelled %0d turns; its FIFO held up to %0d of %0d flits (%0d regular at most, bypass space %0d)",
                           dst, t_end + 200 - (r0 - 110), v_rcx[dst] - c0, v_fifo[dst], EJ_DEPTH, NUM_VC * VC_DEPTH, SPACE));
    `TB_CHECK(v_fifo[dst] > longint'(NUM_VC * VC_DEPTH),
              ("BP07 b: the stalled FIFO held at most %0d flits; the test should fill it past the %0d regular ones", v_fifo[dst], NUM_VC * VC_DEPTH))
    r0 = round_start(cyc + 200);
    bad = 0;
    for (int s = 0; s < BNS; s++) begin
      in_cycle(r0 + s * BSL);
      if (sum_res() != 0) bad++;
    end
    `TB_CHECK(bad == 0, ("BP07 b: after the stall, reservations still held at %0d slot boundaries", bad))
    traffic_pkg::dlog.delete();
    src = 0;
    ok  = find_sub(src, dst, sl, k, mode);
    `TB_CHECK(ok, ("BP07: the timetable never lets R%0d send to R%0d", src, dst))
    t   = sub_start(sl, k, cyc + BYP_LEAD + 2);
    at_cycle(t - BYP_LEAD);
    hold_req[src] = 5'b10000;
    traffic_pkg::direct(src, dst, MAX_PKT_FLITS);
    at_cycle(t - 1);
    hold_req[src] = '0;
    wait_delivered("BP07 b after");
    check_burst("BP07 b after the stall", src, dst, t, MAX_PKT_FLITS, blen);
    tb_pkg::info($sformatf("BP07 b: after the stall R%0d accepted R%0d's turn at cycle %0d and the burst landed on time; the largest FIFO occupancy the model saw anywhere was %0d",
                           dst, src, t, nmax));
    traffic_pkg::log_on = 1'b0;
    check_idle("BP07");
    traffic_defaults();
  endtask

  task automatic bp08();
    bit              ok;
    int unsigned     load, dl0, n_cyc, t_first, cl;
    real             r8;
    string           path;
    longint unsigned u0, p0;
    int              stalls0, clen;
    if (NUM_VC != 1) begin
      tb_pkg::fail($sformatf("BP08 needs one VC (+define+TB_NUM_VC=1); this bench has %0d", NUM_VC));
      return;
    end
    if (!$value$plusargs("BP08_RATE=%f", r8)) r8 = 0.3;
    load = quick() ? 1000 : 3000;
    if (DESIGN == DESIGN_A) begin
      bp08_a(r8, load);
      return;
    end
    tb_pkg::phase($sformatf("BP08 deadlock recovery: 1 VC, adaptive routing, uniform at %0.3f packets/node/cycle for %0d cycles or until a cycle of waiting packets forms (at most %0d); a delivery at least once per round (%0d cycles)",
                            r8, load, 4 * load, BRL));
    traffic_defaults();
    traffic_pkg::rate = r8;
    stats_pkg::reset(NN);
    stalls0 = u_rc.stalls;
    dl0 = u_rc.dl_limit;
    u_rc.dl_limit = BRL + 2 * sched_pkg::hmax(MESH_N) + B_MAX + 50;   // one round: every waiting packet's turn comes
    u0 = sum_of(v_used);
    p0 = sum_of(v_bpkts);
    n_cyc   = 0;
    t_first = 0;
    traffic_pkg::gen_on = 1'b1;
    sb_pkg::last_delivery = cyc;
    for (int unsigned c = 0; c < load || (n_cyc == 0 && c < 4 * load); c++) begin
      @(posedge clk);
      if (u_rc.deadlocked()) break;
      if (c % 50 == 0) begin
        clen = wait_cycle(path);
        if (clen >= 2) begin
          n_cyc++;
          if (t_first == 0) begin
            t_first = cyc;
            cl      = clen;
            tb_pkg::info($sformatf("BP08: at cycle %0d, %0d packets wait in a cycle, each for the input VC the next one holds:%s",
                                   cyc, clen, path));
          end
        end
      end
    end
    traffic_pkg::gen_on = 1'b0;
    `TB_CHECK(!u_rc.deadlocked(), ("BP08: no delivery for %0d cycles while generating", u_rc.dl_limit))
    u_rc.drain(DRAIN_MAX, ok);
    u_rc.dl_limit = dl0;
    `TB_CHECK(ok && u_rc.stalls == stalls0, ("BP08: %s", why_stuck(stalls0, DRAIN_MAX)))
    stop_if(ok, "BP08");
    if (!quick()) begin
      `TB_CHECK(n_cyc >= 1, ("BP08: no cycle of waiting packets formed; raise +BP08_RATE"))
    end
    tb_pkg::info($sformatf("BP08: cycles of waiting packets seen in %0d samples (first at cycle %0d, %0d packets); all broken: %0d bursts carried %0d packets, every packet delivered",
                           n_cyc, t_first, cl, sum_of(v_used) - u0, sum_of(v_bpkts) - p0));
    if (quick()) tb_pkg::cover_goal("BP08 samples with a cycle of waiting packets", longint'(n_cyc));
    else         tb_pkg::cover_bin("BP08 samples with a cycle of waiting packets", longint'(n_cyc));
    check_idle("BP08");
    traffic_defaults();
  endtask

  task automatic bp08_a(real r8, int unsigned load);
    bit          ok;
    int          clen;
    string       path;
    int unsigned t0;
    tb_pkg::phase($sformatf("BP08 design A: 1 VC, adaptive routing, uniform at %0.3f packets/node/cycle for %0d cycles: expected to deadlock",
                            r8, load));
    traffic_defaults();
    traffic_pkg::rate = r8;
    stats_pkg::reset(NN);
    t0 = cyc;
    traffic_pkg::gen_on = 1'b1;
    u_rc.wait_cycles(load, ok);
    traffic_pkg::gen_on = 1'b0;
    if (ok) u_rc.drain(DRAIN_MAX, ok);
    `TB_CHECK(!ok && u_rc.stalls == 1, ("BP08 design A: no deadlock (it drained)"))
    if (ok) return;
    clen = wait_cycle(path);
    `TB_CHECK(clen >= 2, ("BP08 design A: frozen, but no cycle of waiting packets found"))
    tb_pkg::info($sformatf("BP08 design A: deadlock, the last delivery at cycle %0d (%0d cycles after the load started); %0d packets wait in a cycle:%s",
                           u_rc.t_stall, u_rc.t_stall - t0, clen, path));
    tb_pkg::cover_bin("BP08 design A cycles to deadlock", longint'(u_rc.t_stall) - longint'(t0));
  endtask

  task automatic bp10();
    int unsigned     meas;
    real             share, sflit, r10;
    perf_pkg::snap_t a, b;
    longint unsigned bp0, ck0, cx0;
    meas = quick() ? 1500 : 10000;
    r10  = 0.20 * sat_rate() / 0.257;
    tb_pkg::phase($sformatf("BP10 bypass share: uniform at %0.3f packets/node/cycle (78%% of design A's saturation), %0d cycles measured",
                            r10, meas));
    traffic_defaults();
    traffic_pkg::rate = r10;
    a   = perf_snap();
    bp0 = sum_of(v_bpkts);
    ck0 = (rchk_pkg::the_chk == null) ? 0 : rchk_pkg::the_chk.n_pkts;
    cx0 = (nchk_pkg::the_nchk == null) ? 0 : nchk_pkg::the_nchk.n_cxl;
    load_phase("BP10", meas / 5, meas);
    report("BP10");
    b     = perf_snap();
    share = stats_pkg::byp_pkt();
    sflit = stats_pkg::byp_flit();
    `TB_CHECK(b.cxl - a.cxl == 0 && b.rcx - a.rcx == 0,
              ("BP10: %0d turns cancelled (%0d by the NIs) while every sink kept up", b.cxl - a.cxl, b.rcx - a.rcx))
    if (nchk_pkg::the_nchk != null) begin
      `TB_CHECK(nchk_pkg::the_nchk.n_cxl - cx0 == 0, ("BP10: the NI model cancelled %0d turns", nchk_pkg::the_nchk.n_cxl - cx0))
    end
    if (rchk_pkg::the_chk != null) begin
      `TB_CHECK(rchk_pkg::the_chk.n_pkts - ck0 == sum_of(v_bpkts) - bp0,
                ("BP10: the checker counted %0d bypassed packets, the sources sent %0d", rchk_pkg::the_chk.n_pkts - ck0, sum_of(v_bpkts) - bp0))
    end
    `TB_CHECK(share > 0.0 && share < 1.0 && b.used > a.used,
              ("BP10: bypass share %0.4f of the measured packets, %0d bursts", share, b.used - a.used))
    tb_pkg::info($sformatf("BP10: bypass share %0.2f%% of packets, %0.2f%% of flits; %0d bursts in %0d turns (%0.2f%%), none cancelled; [1] reports 49-73%% (open question for E0)",
                           100.0 * share, 100.0 * sflit, b.used - a.used, b.turns - a.turns,
                           100.0 * real'(b.used - a.used) / real'((b.turns > a.turns) ? b.turns - a.turns : 1)));
    tb_pkg::csv({stats_pkg::csv_header(), ",", perf_pkg::header()});
    tb_pkg::csv({stats_pkg::csv_row($sformatf("BP10_N%0d_V%0d", MESH_N, NUM_VC), "B", MESH_N, NUM_VC, "uniform", 1.0 / 3.0, r10,
                                    tb_pkg::seed, u_rc.stalls, u_rc.t_stall, meas, $sformatf("%0d", B_MAX), tmode_name()),
                 ",", perf_pkg::row(a, b)});
    tb_pkg::cover_bin("BP10 packets by bypass", sum_of(v_bpkts) - bp0);
    traffic_defaults();
  endtask
  /* verilator lint_on UNUSEDSIGNAL */
// ---- end tb/mesh/tests_resv.svh
// ---- begin tb/mesh/tests_two.svh

  /* verilator lint_off UNUSEDSIGNAL */

  localparam int CTL = sched_pkg::t_sub(REGION_N, B_MAX, T_MODE);   // local subslot, cycles
  localparam int CSU = sched_pkg::s_setup(REGION_N);                // local setup window
  localparam int CLS = sched_pkg::slot_len(REGION_N, CTL);          // local slot
  localparam int CLR = sched_pkg::n_slots(REGION_N);                // local slots per round
  localparam int CNR = (MESH_N / REGION_N) * (MESH_N / REGION_N);   // regions
  localparam int TL_LEAD = 30;                                      // inject this long before the turn
  localparam int ADM1    = sched_pkg::A_DELAY - 1;                   // the sample's cycle in an epoch
  localparam int KMX     = sched_pkg::k_max(MESH_N);                // D18's K_MAX

  typedef struct {
    int src;
    int dst;
    int t;          // the subslot's first cycle
    bit loc;
    int slot;
    int sub;
  } turn_t;

  typedef turn_t turn_q_t[$];

  function automatic longint flen_c(int k);
    return longint'(k) * longint'(CLS) + longint'(BSL);
  endfunction

  function automatic int reg_c(int r);
    return ((r / MESH_N) / REGION_N) * (MESH_N / REGION_N) + (r % MESH_N) / REGION_N;
  endfunction

  function automatic int cur_kl();
    return int'(p_st[0].kl);
  endfunction

  function automatic turn_q_t turns_in(int unsigned a, int unsigned b);
    turn_q_t                q;
    turn_t                  tn;
    sched_ref_pkg::fpos_t   fp;
    sched_ref_pkg::pos_t    pz;
    sched_ref_pkg::xfer_q_t x;
    q = {};
    for (int unsigned c = a; c < b; c++) begin
      fp = sched_ref_pkg::the_fr.at(longint'(c) - longint'(c_rst));
      if (fp.loc) pz = fp.lp;
      else        pz = fp.gp;
      if (pz.setup || pz.cyc != 0) continue;
      x = sched_ref_pkg::ref_mesh_xfers(MESH_N, REGION_N, fp.loc, pz.slot, pz.sub);
      foreach (x[m]) begin
        tn.src  = x[m].sy * MESH_N + x[m].sx;
        tn.dst  = x[m].dy * MESH_N + x[m].dx;
        tn.t    = int'(c);
        tn.loc  = fp.loc;
        tn.slot = pz.slot;
        tn.sub  = pz.sub;
        q.push_back(tn);
      end
    end
    return q;
  endfunction

  function automatic int unsigned glob_round_start(int unsigned c);
    sched_ref_pkg::fpos_t fp;
    int unsigned          u;
    u = c;
    fp = sched_ref_pkg::the_fr.at(longint'(u) - longint'(c_rst));
    while (fp.loc || !(fp.gp.setup && fp.gp.cyc == 0 && fp.gp.slot == 0)) begin
      u++;
      fp = sched_ref_pkg::the_fr.at(longint'(u) - longint'(c_rst));
    end
    return u;
  endfunction

  function automatic int unsigned slot_start(int unsigned c);
    sched_ref_pkg::fpos_t fp;
    sched_ref_pkg::pos_t  pz;
    int unsigned          u;
    u = c;
    while (1) begin
      fp = sched_ref_pkg::the_fr.at(longint'(u) - longint'(c_rst));
      if (fp.loc) pz = fp.lp;
      else        pz = fp.gp;
      if (pz.setup && pz.cyc == 0) break;
      u++;
    end
    return u;
  endfunction

  function automatic int unsigned frame_start(int unsigned c);
    return int'(sched_ref_pkg::the_fr.next_frame(longint'(c) - longint'(c_rst)) + longint'(c_rst));
  endfunction

  function automatic int unsigned next_sample(int unsigned c);
    longint e, m;
    e = longint'(c) - longint'(c_rst);
    m = (e - longint'(ADM1) + longint'(EPOCH) - 1) / longint'(EPOCH);
    if (e <= longint'(ADM1)) m = 0;
    return int'(longint'(c_rst) + m * longint'(EPOCH) + longint'(ADM1));
  endfunction

  task automatic set_plan(string what, int k, output int unsigned t_set, output int unsigned t_sw);
    int unsigned tmax;
    @(posedge clk);
    t_set    = cyc + 1;                // cyc still names the cycle this edge ends
    plan_req = sched_pkg::kl_t'(k);
    tmax     = t_set + 2 * EPOCH + int'(flen_c(63)) + 10;
    do @(negedge clk); while (cur_kl() != k && cyc < tmax);
    t_sw = cyc;
    `TB_CHECK(cur_kl() == k, ("%s: plan %0d reached the tiles in cycle %0d; they still run k_L %0d at cycle %0d", what, k, t_set,
                              cur_kl(), cyc))
  endtask

  task automatic held_turns(string what, turn_q_t q, int npk, output int n_ok);
    int                 L, src, dst, n_exp, flen, n_bad;
    int unsigned        t_end, t_cur, t_rel [NN];
    longint unsigned    u0, c0x;
    traffic_pkg::dlog_t d;
    int                 tq [NN][NN];
    for (int s = 0; s < NN; s++) begin
      t_rel[s] = 0;
      for (int dd = 0; dd < NN; dd++) tq[s][dd] = 0;
    end
    flen = (B_MAX >= MAX_PKT_FLITS) ? MAX_PKT_FLITS : 1;
    traffic_pkg::dlog.delete();
    traffic_pkg::log_on = 1'b1;
    n_exp = 0;
    u0    = sum_of(v_used);
    c0x   = sum_of(v_cxl);
    t_end = 0;
    t_cur = 0;
    foreach (q[m]) begin
      if (q[m].t > t_cur) begin
        at_cycle(q[m].t - TL_LEAD);
        t_cur = q[m].t;
      end
      src = q[m].src;
      dst = q[m].dst;
      `TB_CHECK(tq[src][dst] == 0, ("%s: R%0d -> R%0d listed twice", what, src, dst))
      tq[src][dst]  = q[m].t;
      hold_req[src] = 5'b10000;
      if (q[m].t + 2 > t_rel[src]) t_rel[src] = q[m].t + 2;
      for (int i = 0; i < npk; i++) traffic_pkg::direct(src, dst, flen);
      n_exp += npk;
      if (q[m].t > t_end) t_end = q[m].t;
      for (int s = 0; s < NN; s++) if (t_rel[s] != 0 && t_rel[s] + TL_LEAD < cyc) begin
        hold_req[s] = '0;
        t_rel[s]    = 0;
      end
    end
    at_cycle(t_end + 2 * sched_pkg::hmax(MESH_N) + B_MAX + 4);
    for (int s = 0; s < NN; s++) hold_req[s] = '0;
    wait_delivered(what);
    n_ok  = 0;
    n_bad = 0;
    foreach (traffic_pkg::dlog[i]) begin
      d   = traffic_pkg::dlog[i];
      src = int'(d.src);
      dst = int'(d.dst);
      L   = nhops(src, dst);
      if (d.byp && tq[src][dst] != 0 && d.t_tail <= tq[src][dst] + sched_pkg::tc_eject(L, B_MAX - 1) &&
          d.t_tail >= tq[src][dst] + sched_pkg::tc_eject(L, flen - 1)) begin
        n_ok++;
      end else if (n_bad < 10) begin
        n_bad++;
        tb_pkg::info($sformatf("%s: packet %0d.%0d R%0d -> R%0d: bypass %0b, tail at %0d, its turn at %0d", what,
                               d.src, d.seq, d.src, d.dst, d.byp, d.t_tail, tq[src][dst]));
      end
    end
    `TB_CHECK(traffic_pkg::dlog.size() == n_exp && n_ok == n_exp,
              ("%s: %0d packets delivered, %0d of them by bypass in their own turn's burst; expected %0d", what,
               traffic_pkg::dlog.size(), n_ok, n_exp))
    `TB_CHECK(sum_of(v_cxl) - c0x == 0, ("%s: %0d turns cancelled", what, sum_of(v_cxl) - c0x))
    tb_pkg::info($sformatf("%s: %0d packets, %0d bursts, every packet by bypass in its own turn", what, n_exp,
                           sum_of(v_used) - u0));
    traffic_pkg::log_on = 1'b0;
  endtask

  task automatic tl01();
    turn_q_t         q, all;
    bit              got_reg [CNR];
    bit              got_x;
    int              n_ok, nfr, nlr;
    int unsigned     ncyc;
    longint unsigned lb0 [CNR];
    longint unsigned xf0, ct0, lt0;
    tb_pkg::phase($sformatf("TL01 regions are isolated: %0d regions of %0dx%0d, k_L %0d", CNR, REGION_N, REGION_N, cur_kl()));
    traffic_defaults();
    xf0 = mchk_pkg::the_mchk.n_xflits;
    for (int r = 0; r < CNR; r++) lb0[r] = longint'(rchk_pkg::the_chk.lb_reg[r]);
    all   = turns_in(cyc + 2 * TL_LEAD, cyc + 2 * TL_LEAD + 2 * int'(flen_c(cur_kl())));
    q     = {};
    got_x = 1'b0;
    for (int r = 0; r < CNR; r++) got_reg[r] = 1'b0;
    foreach (all[m]) begin
      if (all[m].loc) begin
        if (!got_reg[reg_c(all[m].src)]) begin
          got_reg[reg_c(all[m].src)] = 1'b1;
          q.push_back(all[m]);
        end
      end else if (!got_x && reg_c(all[m].src) != reg_c(all[m].dst)) begin
        got_x = 1'b1;
        q.push_back(all[m]);
      end
    end
    `TB_CHECK(q.size() == CNR + 1, ("TL01: found %0d held turns, expected one local turn per region (%0d) and one cross-region turn",
                                    q.size(), CNR))
    held_turns("TL01 a", q, 1, n_ok);
    check_idle("TL01 a");
    ct0 = mchk_pkg::the_mchk.n_contain;
    lt0 = smon_pkg::the_smon.n_lturns;
    nfr = (MESH_N >= 16) ? 3 : 6;
    nlr = (MESH_N >= 16) ? 2 : 4;
    ncyc = int'(longint'(nfr) * flen_c(cur_kl())) + nlr * CLR * CLS;
    if (quick()) ncyc = ncyc / 2;
    traffic_pkg::pattern = PAT_REGION;
    traffic_pkg::p_local = 0.7;
    traffic_pkg::rate    = 0.4 * sat_rate();
    tb_pkg::info($sformatf("TL01 b: region traffic, 70%% inside the region, %0.4f packets/node/cycle, %0d cycles", traffic_pkg::rate, ncyc));
    load_phase("TL01 b", 0, ncyc);
    report("TL01 b");
    `TB_CHECK(mchk_pkg::the_mchk.n_contain - ct0 > 0, ("TL01: no local-phase cycle was checked for containment"))
    tb_pkg::info($sformatf("TL01: %0d local-phase cycles checked on every region-crossing link, %0d local turns stayed in their regions, %0d bypass flits crossed a region boundary in global slots",
                           mchk_pkg::the_mchk.n_contain - ct0, smon_pkg::the_smon.n_lturns - lt0, mchk_pkg::the_mchk.n_xflits - xf0));
    tb_pkg::cover_bin("TL01 bursts inside regions in local slots (a)", longint'(n_ok));
    tb_pkg::cover_bin("TL01 bypass flits crossing regions in global slots (a, b)", mchk_pkg::the_mchk.n_xflits - xf0);
    for (int r = 0; r < CNR; r++) begin
      if (r < 4 || r == CNR - 1)
        tb_pkg::cover_bin($sformatf("TL01 local bursts in region %0d (a, b)", r), longint'(rchk_pkg::the_chk.lb_reg[r]) - lb0[r]);
    end
    traffic_defaults();
  endtask

  task automatic tl02();
    turn_q_t         all, q;
    bit              seen [NN][NN];
    int              n_ok, nl, ng;
    int unsigned     r0;
    longint unsigned lr0, gr0;
    longint          gr;
    gr = longint'(BNS) * flen_c(cur_kl());
    r0 = glob_round_start(cyc + 2 * TL_LEAD + 10);
    tb_pkg::phase($sformatf("TL02 every pair is covered: %0d ordered pairs, the global round from cycle %0d (%0d cycles at k_L %0d)",
                            NPAIRS, r0, gr, cur_kl()));
    traffic_defaults();
    lr0 = smon_pkg::the_smon.n_lrounds;
    gr0 = smon_pkg::the_smon.n_grounds;
    all = turns_in(r0, r0 + int'(gr));
    q   = {};
    nl  = 0;
    ng  = 0;
    for (int s = 0; s < NN; s++) for (int d = 0; d < NN; d++) seen[s][d] = 1'b0;
    foreach (all[m]) begin
      if (!seen[all[m].src][all[m].dst]) begin
        seen[all[m].src][all[m].dst] = 1'b1;
        q.push_back(all[m]);
        if (all[m].loc) nl++;
        else            ng++;
      end
    end
    `TB_CHECK(q.size() == NPAIRS, ("TL02: the reference gives %0d ordered pairs a turn in one global round, expected %0d", q.size(), NPAIRS))
    tb_pkg::info($sformatf("TL02: %0d pairs have their first turn in a local slot, %0d in a global slot", nl, ng));
    held_turns("TL02", q, 1, n_ok);
    in_cycle(r0 + int'(gr) + 2);
    `TB_CHECK(smon_pkg::the_smon.n_grounds > gr0 && smon_pkg::the_smon.n_lrounds > lr0,
              ("TL02: the monitor completed %0d global and %0d local rounds during the test", smon_pkg::the_smon.n_grounds - gr0,
               smon_pkg::the_smon.n_lrounds - lr0))
    tb_pkg::info($sformatf("TL02: %0d global and %0d local rounds checked: every pair once per global round, every pair inside a region once per local round",
                           smon_pkg::the_smon.n_grounds - gr0, smon_pkg::the_smon.n_lrounds - lr0));
    check_idle("TL02");
    tb_pkg::cover_bin("TL02 pairs served first by a local turn", longint'(nl));
    tb_pkg::cover_bin("TL02 pairs served first by a global turn", longint'(ng));
    traffic_defaults();
  endtask

  task automatic tl03();
    int              k3, n_ok, nfr, npk, best, L, n_k3;
    int unsigned     t_set, t_sw, f0, tl_last, tg_last;
    string           wh;
    turn_q_t         a, q;
    turn_t           tb;
    longint unsigned xt0, fr0;
    sched_ref_pkg::fpos_t fp;
    k3 = (K_INIT > 1) ? K_INIT - 1 : 2;
    tb_pkg::phase($sformatf("TL03 frames follow the timing rules: k_L = %0d (frames of %0d cycles: %0d local slots of %0d, one global slot of %0d)",
                            k3, flen_c(k3), k3, CLS, BSL));
    traffic_defaults();
    set_plan("TL03", k3, t_set, t_sw);
    tb_pkg::info($sformatf("TL03: plan %0d reached the tiles in cycle %0d, was sampled at the end of cycle %0d, and runs from the frame starting at %0d",
                           k3, t_set, next_sample(t_set), t_sw));
    f0      = frame_start(cyc + 2 * TL_LEAD + 10);
    tl_last = f0 + (k3 - 1) * CLS + CSU + (REGION_N - 1) * CTL;
    tg_last = f0 + k3 * CLS + BS + (MESH_N - 1) * BT;
    npk     = (B_MAX >= MAX_PKT_FLITS) ? B_MAX / MAX_PKT_FLITS : B_MAX;
    if (npk > NUM_VC) npk = NUM_VC;
    q = {};
    for (int w = 0; w < 2; w++) begin
      if (w == 0) begin
        a  = turns_in(tl_last, tl_last + 1);
        wh = "last local";
      end else begin
        a  = turns_in(tg_last, tg_last + 1);
        wh = "global";
      end
      best = -1;
      L    = -1;
      foreach (a[m]) begin
        if (nhops(a[m].src, a[m].dst) > L) begin
          L    = nhops(a[m].src, a[m].dst);
          best = m;
        end
      end
      `TB_CHECK(best >= 0, ("TL03: no transfer in the last subslot of the %s slot of the frame at cycle %0d", wh, f0))
      if (best >= 0) begin
        tb = a[best];
        q.push_back(tb);
        tb_pkg::info($sformatf("TL03: %0d packets R%0d -> R%0d (%0d hops) for the last subslot of the %s slot, cycle %0d",
                               npk, tb.src, tb.dst, L, wh, tb.t));
      end
    end
    xt0 = rchk_pkg::the_chk.n_xtail;
    held_turns("TL03 boundaries", q, npk, n_ok);
    check_idle("TL03 boundaries");
    nfr = quick() ? 4 : 12;
    fr0 = mchk_pkg::the_mchk.n_frames;
    traffic_pkg::pattern = PAT_REGION;
    traffic_pkg::p_local = 0.5;
    traffic_pkg::rate    = 0.4 * sat_rate();
    load_phase("TL03 frames", 0, int'(longint'(nfr) * flen_c(k3)));
    report("TL03 frames");
    n_k3 = int'(mchk_pkg::the_mchk.n_frames - fr0);
    `TB_CHECK(cur_kl() == k3 && n_k3 >= nfr, ("TL03: %0d frames checked with k_L %0d (now %0d), expected at least %0d", n_k3, k3, cur_kl(), nfr))
    tb_pkg::info($sformatf("TL03: %0d frames of k_L %0d checked: lengths, setup windows, resumed slot numbers", n_k3, k3));
    tb_pkg::cover_bin("TL03 bursts whose last flits land in the other phase", rchk_pkg::the_chk.n_xtail - xt0);
    traffic_defaults();
  endtask

  task automatic tl04();
    int              plans [4];
    int              k, n_sw, res_at, rmax, n_after;
    int unsigned     t_set, t_sw, s_exp, f_exp, wait_c, t_b, t_bs, u;
    longint unsigned cx0, ac0;
    int              res_any, n_late, lim, nq;
    plans   = '{0, KMX, 1, 3};
    res_any = 0;
    tb_pkg::phase($sformatf("TL04 plan changes are clean: k_L %0d -> %0d -> %0d -> %0d -> %0d, each at a random point of an epoch of %0d cycles",
                            cur_kl(), plans[0], plans[1], plans[2], plans[3], EPOCH));
    traffic_defaults();
    traffic_pkg::pattern      = PAT_REGION;
    traffic_pkg::p_local      = 0.5;
    traffic_pkg::rate         = 0.3 * sat_rate();
    traffic_pkg::sink_stall_p = 0.3;
    traffic_pkg::gen_on       = 1'b1;
    cx0     = sum_of(v_rcx);
    ac0     = sum_of(v_acc);
    n_sw    = 0;
    n_after = 0;
    for (int i = 0; i < 4; i++) begin
      k      = plans[i];
      wait_c = tb_pkg::rng_below(SID, EPOCH);
      repeat (wait_c) @(posedge clk);
      set_plan($sformatf("TL04 plan %0d", k), k, t_set, t_sw);
      s_exp  = next_sample(t_set);
      f_exp = frame_start(s_exp + 1);
      `TB_CHECK(t_sw == f_exp && f_exp - (s_exp - (sched_pkg::A_DELAY - 1)) >= sched_pkg::A_DELAY,
                ("TL04: plan %0d set at cycle %0d, sampled at %0d: the tiles switched at cycle %0d, expected the frame start at %0d",
                 k, t_set, s_exp, t_sw, f_exp))
      res_at = sum_res();
      if (res_at > 0) res_any++;
      rmax = 0;
      u    = slot_start(t_sw + 1);
      while (cyc < u) begin
        @(negedge clk);
        if (sum_res() > rmax) rmax = sum_res();
      end
      if (rmax > 0) n_after++;
      n_sw++;
      tb_pkg::info($sformatf("TL04: plan %0d reached the tiles in cycle %0d, sampled at the end of cycle %0d; every tile switched at the frame start %0d; %0d flits reserved then, up to %0d in the first slot after",
                             k, t_set, s_exp, t_sw, res_at, rmax));
    end
    traffic_pkg::gen_on       = 1'b0;
    traffic_pkg::sink_stall_p = 0.0;
    wait_delivered("TL04");
    check_idle("TL04");
    u = slot_start(cyc + 2);
    in_cycle(u - 1);
    n_late = 0;
    lim    = int'(u) - 1;
    for (int r = 0; r < NN; r++) begin
      nq = nchk_pkg::the_nchk.wdue[r].size();
      for (int i = 0; i < nq; i++) if (nchk_pkg::the_nchk.wdue[r][i] > lim) n_late++;
    end
    `TB_CHECK(n_late == 0 && sum_res() == B_MAX * nchk_pkg::the_nchk.waiting(),
              ("TL04: at the end of the slot before cycle %0d, %0d reservations are due after the slot ends; %0d flits reserved for %0d open reservations",
               u, n_late, sum_res(), nchk_pkg::the_nchk.waiting()))
    tb_pkg::info($sformatf("TL04: %0d plan switches, %0d reservations accepted and %0d cancelled meanwhile, none lost",
                           n_sw, sum_of(v_acc) - ac0, sum_of(v_rcx) - cx0));
    tb_pkg::cover_bin("TL04 plan switches with every tile in step", longint'(n_sw));
    tb_pkg::cover_bin("TL04 switches followed by reservations of the new phase", longint'(n_after));
    tb_pkg::cover_goal("TL04 switches with reservations open from before", longint'(res_any));
    tb_pkg::cover_goal("TL04 turns cancelled by a full NI meanwhile", sum_of(v_rcx) - cx0);
    set_plan("TL04 back to K_FIXED", K_INIT, t_b, t_bs);
    traffic_defaults();
  endtask

  task automatic tl05();
    int unsigned     ncyc;
    longint unsigned u0, s0, x0;
    ncyc = (MESH_N <= 4) ? 4000 : 12000;
    if (quick()) ncyc = ncyc / 3;
    if (REGION_N == MESH_N)
      tb_pkg::phase($sformatf("TL05 design C with one %0dx%0d region (D50) against design B, every output and link every cycle, %0d cycles of traffic",
                              REGION_N, REGION_N, ncyc));
    else
      tb_pkg::phase($sformatf("TL05 design C with k_L = %0d against design B, every output and link every cycle, %0d cycles of traffic",
                              K_INIT, ncyc));
    `TB_CHECK(REGION_N == MESH_N || K_INIT == 0, ("TL05: needs one region or k_L = 0 (REGION_N %0d, K_INIT %0d)", REGION_N, K_INIT))
    traffic_defaults();
    traffic_pkg::pattern      = PAT_REGION;
    traffic_pkg::p_local      = 0.5;
    traffic_pkg::rate         = 0.5 * sat_rate();
    traffic_pkg::sink_stall_p = 0.1;
    traffic_pkg::fs_node      = FS_ALL;
    traffic_pkg::fs_start     = cyc + ncyc / 2;
    traffic_pkg::fs_end       = cyc + ncyc / 2 + 500;
    u0 = sum_of(v_used);
    x0 = sum_of(v_cxl);
    s0 = sh_same;
    load_phase("TL05", 0, ncyc);
    report("TL05");
    traffic_defaults();
    if (!quick()) bp06();
    `TB_CHECK(!sh_diff && sh_same - s0 > longint'(ncyc),
              ("TL05: the meshes agreed for %0d cycles of the test (differed: %0b)", sh_same - s0, sh_diff))
    tb_pkg::info($sformatf("TL05: design C and design B agreed on every output and link for %0d cycles; %0d bursts, %0d turns cancelled",
                           sh_same - s0, sum_of(v_used) - u0, sum_of(v_cxl) - x0));
    tb_pkg::cover_bin("TL05 bursts in both meshes", sum_of(v_used) - u0);
    if (quick()) tb_pkg::cover_goal("TL05 turns cancelled in both meshes", sum_of(v_cxl) - x0);
    else         tb_pkg::cover_bin("TL05 turns cancelled in both meshes", sum_of(v_cxl) - x0);
    traffic_defaults();
  endtask

  function automatic int sched_period(int k);
    int f;
    f = BNS;
    while ((f * k) % CLR != 0) f += BNS;
    return f;
  endfunction

  task automatic tl06();
    int unsigned     ncyc, t_set, t_sw, per;
    int              k, gl_max, gl_min, gl_n, gx_max, gx_min, gx_n, bound_l, n_all;
    longint          gr;
    perf_pkg::snap_t a, b;
    real             share;
    if (cur_kl() != K_INIT) set_plan("TL06", K_INIT, t_set, t_sw);
    k   = cur_kl();
    gr  = longint'(BNS) * flen_c(k);
    per = sched_period(k) * int'(flen_c(k));
    if (!$value$plusargs("TL06_CYCLES=%d", ncyc)) begin
      ncyc = per;
      if (longint'(ncyc) < 3 * gr) ncyc = int'(3 * gr);
      if (quick()) ncyc = int'(2 * gr);
    end
    bound_l = CLR * CLS + ((CLR + k - 1) / k) * BSL;
    tb_pkg::phase($sformatf("TL06 turn bounds: %0d cycles of traffic (one schedule period is %0d frames = %0d cycles); bounds: inside a region %0d, across regions %0d",
                            ncyc, sched_period(k), per, bound_l, gr));
    traffic_defaults();
    traffic_pkg::pattern = PAT_REGION;
    traffic_pkg::p_local = 0.5;
    traffic_pkg::rate    = 0.5 * sat_rate();
    smon_pkg::the_smon.clear_gaps();
    a = perf_snap();
    load_phase("TL06", 0, ncyc);
    report("TL06");
    b = perf_snap();
    smon_pkg::the_smon.gaps(1'b1, gl_max, gl_min, gl_n);
    smon_pkg::the_smon.gaps(1'b0, gx_max, gx_min, gx_n);
    n_all = gl_n + gx_n;
    `TB_CHECK(gl_max > 0 && gl_max <= bound_l,
              ("TL06: longest interval between turns of a pair inside a region %0d cycles, bound %0d", gl_max, bound_l))
    if (CNR > 1) begin
      `TB_CHECK(longint'(gx_max) == gr && longint'(gx_min) == gr,
                ("TL06: intervals between turns of a cross-region pair from %0d to %0d cycles, expected exactly one global round, %0d",
                 gx_min, gx_max, gr))
    end
    `TB_CHECK(n_all == NPAIRS, ("TL06: %0d of the %0d ordered pairs had two turns or more", n_all, NPAIRS))
    `TB_CHECK(b.cxl - a.cxl == 0, ("TL06: %0d turns cancelled while every sink kept up", b.cxl - a.cxl))
    share = stats_pkg::byp_pkt();
    tb_pkg::info($sformatf("TL06: inside a region turns every %0d..%0d cycles (bound %0d, %0d pairs); across regions every %0d..%0d (one global round %0d, %0d pairs)",
                           gl_min, gl_max, bound_l, gl_n, gx_min, gx_max, gr, gx_n));
    tb_pkg::info($sformatf("TL06: bypass share %0.2f%% of packets; %0d bursts in %0d turns, none cancelled", 100.0 * share,
                           b.used - a.used, b.turns - a.turns));
    tb_pkg::cover_bin("TL06 pairs inside regions measured", longint'(gl_n));
    if (CNR > 1) tb_pkg::cover_bin("TL06 cross-region pairs measured", longint'(gx_n));
    traffic_defaults();
  endtask

  function automatic void tl_summary();
    if (smon_pkg::the_smon == null) return;
    tb_pkg::info($sformatf("design C run: %0d local and %0d global subslots checked tile by tile, %0d local and %0d global turns, %0d local and %0d global rounds checked pair by pair",
                           smon_pkg::the_smon.n_lsub, smon_pkg::the_smon.n_gsub, smon_pkg::the_smon.n_lturns,
                           smon_pkg::the_smon.n_gturns, smon_pkg::the_smon.n_lrounds, smon_pkg::the_smon.n_grounds));
    tb_pkg::info($sformatf("design C run: %0d frames checked, %0d k_L changes, %0d local-phase cycles checked for containment, %0d lookaheads followed on links and %0d at NIs",
                           mchk_pkg::the_mchk.n_frames, mchk_pkg::the_mchk.n_k_changes, mchk_pkg::the_mchk.n_contain,
                           mchk_pkg::the_mchk.n_ann, mchk_pkg::the_mchk.n_nian));
    tb_pkg::info($sformatf("design C run: %0d bursts (%0d in local slots), %0d whose last flits landed in the other phase",
                           rchk_pkg::the_chk.n_bursts, rchk_pkg::the_chk.n_lbursts, rchk_pkg::the_chk.n_xtail));
  endfunction

  /* verilator lint_on UNUSEDSIGNAL */
// ---- end tb/mesh/tests_two.svh
// ---- begin tb/mesh/tests_ctrl.svh

  /* verilator lint_off UNUSEDSIGNAL */

  localparam int CT_KMAX = K_HI;

  function automatic int ep_of(int unsigned c);
    int a, b;
    a = int'(c);
    b = int'(c_rst);
    return (a - b) / EPOCH;
  endfunction

  function automatic int unsigned ep_t0(int m);
    int unsigned o;
    o = m * EPOCH;
    return c_rst + o;
  endfunction

  function automatic int plan_of(int m);
    if (cchk_pkg::the_cchk == null) return -1;
    if (m < 0 || m >= cchk_pkg::the_cchk.kq.size()) return -1;
    return cchk_pkg::the_cchk.kq[m];
  endfunction

  task automatic ct_config();
    string pol;
    int    dmp;
    if ($value$plusargs("POLICY=%s", pol)) begin
      if (pol == "SQRT" || pol == "sqrt") ctrl_pol = 1'b1;
    end
    if ($value$plusargs("DAMP=%d", dmp)) ctrl_damp = (dmp != 0);
    tb_pkg::info($sformatf("design D controller: policy %s, damping %0d, epochs of %0d cycles, k_L %0d..%0d from %0d",
                           pol_name(), ctrl_damp, EPOCH, K_LO, CT_KMAX, K_INIT));
  endtask

  function automatic string pol_name();
    string s;
    if (ctrl_pol) s = "SQRT";
    else          s = "PROP";
    return s;
  endfunction

  task automatic to_tick();
    int unsigned t;
    t = ep_t0(ep_of(cyc) + 1);
    while (cyc + 1 < t) @(posedge clk);
  endtask

  task automatic ct_phase(string what, int n, output int m0);
    bit ok;
    to_tick();
    m0 = ep_of(cyc + 1);
    traffic_pkg::gen_on = 1'b1;
    u_rc.wait_cycles(n * EPOCH, ok);
    `TB_CHECK(ok, ("%s: deadlock, no packet delivered since cycle %0d", what, sb_pkg::last_delivery))
    stop_if(ok, what);
  endtask

  task automatic ct_drain(string what);
    bit ok;
    traffic_pkg::gen_on = 1'b0;
    u_rc.drain(DRAIN_MAX, ok);
    `TB_CHECK(ok, ("%s: the mesh did not drain", what))
    stop_if(ok, what);
    check_idle(what);
  endtask

  function automatic string plans(int a, int b);
    string s;
    s = "";
    for (int m = a; m <= b; m++) begin
      if (m > a) s = {s, " "};
      s = {s, $sformatf("%0d", plan_of(m))};
    end
    return s;
  endfunction

  task automatic ct01();
    int              m0, k_prev, n_sw, d_min, d_max, d, lim, li;
    longint          lf;
    int unsigned     t_end, ph;
    tb_pkg::phase("CT01 epoch timing: uniform traffic for 6 epochs; every k_L switch at a frame start, at least A_DELAY after its tick");
    traffic_defaults();
    traffic_pkg::pattern = PAT_UNIFORM;
    traffic_pkg::rate    = 0.4 * sat_rate();
    to_tick();
    m0     = ep_of(cyc + 1);
    t_end  = ep_t0(m0 + 6);
    k_prev = cur_kl();
    n_sw   = 0;
    d_min  = EPOCH;
    d_max  = 0;
    traffic_pkg::gen_on = 1'b1;
    while (cyc + 1 < t_end) begin
      @(posedge clk);
      if (cur_kl() != k_prev) begin
        ph  = (cyc - c_rst) % EPOCH;
        d   = int'(ph);
        lf  = flen_c(k_prev);
        li  = int'(lf);
        lim = sched_pkg::A_DELAY - 1 + li;
        `TB_CHECK(d >= sched_pkg::A_DELAY && d <= lim && p_st[0].lc == 0,
                  ("CT01: k_L %0d -> %0d in cycle %0d of its epoch, expected a frame start in %0d..%0d", k_prev, cur_kl(), d,
                   sched_pkg::A_DELAY, lim))
        if (d < d_min) d_min = d;
        if (d > d_max) d_max = d;
        n_sw++;
        k_prev = cur_kl();
      end
    end
    ct_drain("CT01");
    tb_pkg::info($sformatf("CT01: plans of epochs %0d..%0d: %s; %0d switches, %0d..%0d cycles after the tick; every tile had each new plan by cycle %0d (bound %0d)",
                           m0, m0 + 5, plans(m0, m0 + 5), n_sw, d_min, d_max, cchk_pkg::the_cchk.arr_max,
                           sched_ref_pkg::ref_plan_by(MESH_N)));
    tb_pkg::cover_bin("CT01 k_L switches", longint'(n_sw));
    traffic_defaults();
  endtask

  task automatic ct02();
    int     m0, m1, m2, m3, np, k1, k1n, k2, k2n;
    longint nreg;
    np = quick() ? 3 : 4;
    tb_pkg::phase($sformatf("CT02 the controller follows demand: uniform, region (p_local 0.75), uniform; %0d epochs each", np));
    traffic_defaults();
    traffic_pkg::rate    = 0.4 * sat_rate();
    traffic_pkg::pattern = PAT_UNIFORM;
    ct_phase("CT02 uniform", np, m0);
    traffic_pkg::pattern = PAT_REGION;
    traffic_pkg::p_local = 0.75;
    ct_phase("CT02 region", np, m1);
    traffic_pkg::pattern = PAT_UNIFORM;
    ct_phase("CT02 uniform again", np, m2);
    m3 = m2 + np;
    ct_drain("CT02");
    k1  = plan_of(m1);
    k1n = plan_of(m1 + 1);
    k2  = plan_of(m2);
    k2n = plan_of(m2 + 1);
    tb_pkg::info($sformatf("CT02 (%s, damping %0d): plans uniform %s | region %s | uniform %s", pol_name(), ctrl_damp,
                           plans(m0, m1 - 1), plans(m1, m2 - 1), plans(m2, m3 - 1)));
    `TB_CHECK(k1n > k1, ("CT02: k_L did not rise in the first epoch planned from region traffic: plan %0d, then %0d", k1, k1n))
    `TB_CHECK(k2n < k2, ("CT02: k_L did not fall in the first epoch planned from uniform traffic again: plan %0d, then %0d", k2, k2n))
    k1   = m2 - m1;
    nreg = longint'(k1);
    tb_pkg::cover_bin("CT02 epochs planned from region traffic", nreg);
    traffic_defaults();
  endtask

  task automatic ct03();
    int  m0, m1, ns, lo, hi, lo2, hi2, k;
    bit  d0;
    ns = quick() ? 6 : 10;
    tb_pkg::phase($sformatf("CT03 the loop is stable: region traffic (p_local 0.5) for %0d epochs with damping, then 4 without", ns));
    d0 = ctrl_damp;
    traffic_defaults();
    traffic_pkg::pattern = PAT_REGION;
    traffic_pkg::p_local = 0.5;
    traffic_pkg::rate    = 0.4 * sat_rate();
    ctrl_damp = 1'b1;
    ct_phase("CT03 damped", ns, m0);
    ctrl_damp = 1'b0;
    ct_phase("CT03 undamped", 4, m1);
    ct_drain("CT03");
    ctrl_damp = d0;
    lo = 99;
    hi = -1;
    for (int m = m0 + 4; m < m1; m++) begin
      k = plan_of(m);
      if (k < lo) lo = k;
      if (k > hi) hi = k;
    end
    lo2 = 99;
    hi2 = -1;
    for (int m = m1; m < m1 + 4; m++) begin
      k = plan_of(m);
      if (k >= 0 && k < lo2) lo2 = k;
      if (k > hi2) hi2 = k;
    end
    tb_pkg::info($sformatf("CT03 (%s): plans with damping %s (settled %0d..%0d); without %s (%0d..%0d)", pol_name(),
                           plans(m0, m1 - 1), lo, hi, plans(m1, m1 + 3), lo2, hi2));
    `TB_CHECK(hi >= 0 && hi - lo <= 2, ("CT03: with damping k_L ranged %0d..%0d after settling, more than +-1", lo, hi))
    traffic_defaults();
  endtask

  task automatic ct04();
    int          m0, m1, m2, ne, k_end, mx, q_end, k_flr, k_top;
    longint      cg_max;
    int unsigned t;
    bit          ok;
    ne = quick() ? 5 : 6;
    tb_pkg::phase($sformatf("CT04 extremes: traffic only inside regions (%0d epochs), every sink stopped, traffic only across regions (%0d epochs)", ne, ne));
    traffic_defaults();
    traffic_pkg::pattern = PAT_REGION;
    traffic_pkg::p_local = 1.0;
    traffic_pkg::rate    = 0.4 * sat_rate();
    ct_phase("CT04 inside regions", ne, m0);
    ct_drain("CT04 inside regions");
    cg_max = 0;
    for (int m = m0 + 1; m < m0 + ne; m++) begin
      if (m < cchk_pkg::the_cchk.sgq.size() && cchk_pkg::the_cchk.sgq[m] > cg_max) cg_max = cchk_pkg::the_cchk.sgq[m];
    end
    k_end = plan_of(m0 + ne - 1);
    tb_pkg::info($sformatf("CT04 a) inside regions: plans %s; cross-region demand %0d", plans(m0, m0 + ne - 1), cg_max));
    `TB_CHECK(cg_max == 0, ("CT04: cross-region demand %0d with traffic only inside the regions", cg_max))
    `TB_CHECK(k_end == CT_KMAX, ("CT04: k_L %0d after %0d epochs of traffic inside the regions, expected K_MAX %0d", k_end, ne, CT_KMAX))
    traffic_pkg::pattern = PAT_UNIFORM;
    traffic_pkg::rate    = sat_rate();
    to_tick();
    m1 = ep_of(cyc + 1);
    t  = cyc + 1;
    traffic_pkg::fs_node  = FS_ALL;
    traffic_pkg::fs_start = t;
    traffic_pkg::fs_end   = t + 1500;
    traffic_pkg::gen_on   = 1'b1;
    u_rc.wait_cycles(EPOCH, ok);
    `TB_CHECK(ok, ("CT04 sinks stopped: deadlock, no packet delivered since cycle %0d", sb_pkg::last_delivery))
    stop_if(ok, "CT04 sinks stopped");
    ct_drain("CT04 sinks stopped");
    traffic_pkg::fs_node = FS_NONE;
    to_tick();
    repeat (sched_pkg::A_DELAY + 1) @(posedge clk);
    mx = (m1 + 1 < cchk_pkg::the_cchk.mxq.size()) ? cchk_pkg::the_cchk.mxq[m1 + 1] : -1;
    tb_pkg::info($sformatf("CT04 b) sinks stopped: largest sum of one tile %0d (14 bits saturate at %0d), mesh-wide %0d + %0d",
                           mx, cchk_pkg::DMMAX, (m1 + 1 < cchk_pkg::the_cchk.slq.size()) ? cchk_pkg::the_cchk.slq[m1 + 1] : 0,
                           (m1 + 1 < cchk_pkg::the_cchk.sgq.size()) ? cchk_pkg::the_cchk.sgq[m1 + 1] : 0));
    tb_pkg::cover_bin("CT04 epoch with every sink stopped, sums checked", (mx > 0) ? 1 : 0);
    tb_pkg::cover_goal("CT04 a tile's 14-bit sum saturated", cchk_pkg::the_cchk.n_sat);
    traffic_defaults();
    traffic_pkg::pattern = PAT_REGION;
    traffic_pkg::p_local = 0.0;
    traffic_pkg::rate    = 0.4 * sat_rate();
    ct_phase("CT04 across regions", ne, m2);
    ct_drain("CT04 across regions");
    k_end = plan_of(m2 + ne - 1);
    q_end = (m2 + ne - 1 < cchk_pkg::the_cchk.qq.size()) ? cchk_pkg::the_cchk.qq[m2 + ne - 1] : -1;
    k_flr = sched_ref_pkg::ref_kl(cchk_pkg::the_cchk.pol, MESH_N, REGION_N, q_end, K_LO, K_HI);
    k_top = (K_LO > 1) ? K_LO : 1;
    tb_pkg::info($sformatf("CT04 c) across regions: plans %s; share bin of the last epoch %0d, the table's entry %0d",
                           plans(m2, m2 + ne - 1), q_end, k_flr));
    `TB_CHECK(q_end >= 0 && k_end == k_flr && k_flr <= k_top,
              ("CT04: k_L %0d after %0d epochs of traffic across regions (share bin %0d), expected the table's entry %0d, at most %0d (K_MIN %0d)",
               k_end, ne, q_end, k_flr, k_top, K_LO))
    traffic_defaults();
  endtask

  task automatic ct05();
    int          m0, tries, lim, k, gx_max, gx_min, gx_n, gl_max, gl_min, gl_n;
    longint      gr, nb, lgx_max, lgx_min, lgx_n;
    int unsigned t_w0, t_w1, nw;
    bit          ok;
    gr = flen_c(CT_KMAX);
    nb = longint'(BNS);
    gr = gr * nb;
    tb_pkg::phase($sformatf("CT05 the bound at K_MAX: traffic inside regions until k_L = %0d, then two global rounds (%0d cycles each)",
                            CT_KMAX, gr));
    traffic_defaults();
    traffic_pkg::pattern = PAT_REGION;
    traffic_pkg::p_local = 1.0;
    traffic_pkg::rate    = 0.4 * sat_rate();
    tries = 0;
    lim   = 8 * EPOCH;
    k     = cur_kl();
    traffic_pkg::gen_on = 1'b1;
    while (k != CT_KMAX && tries < lim) begin
      @(posedge clk);
      tries++;
      k = cur_kl();
    end
    `TB_CHECK(k == CT_KMAX, ("CT05: k_L is %0d after 8 epochs of traffic inside the regions, expected %0d", k, CT_KMAX))
    smon_pkg::the_smon.clear_gaps();
    t_w0 = cyc;
    if (quick()) nw = int'(gr + gr / 5);
    else         nw = int'(2 * gr + gr / 20);
    u_rc.wait_cycles(nw, ok);
    `TB_CHECK(ok, ("CT05: deadlock, no packet delivered since cycle %0d", sb_pkg::last_delivery))
    stop_if(ok, "CT05");
    t_w1 = cyc;
    smon_pkg::the_smon.gaps(1'b0, gx_max, gx_min, gx_n);
    smon_pkg::the_smon.gaps(1'b1, gl_max, gl_min, gl_n);
    ct_drain("CT05");
    m0 = ep_of(t_w0);
    tb_pkg::info($sformatf("CT05: plans of epochs %0d..%0d: %s; across regions turns every %0d..%0d cycles (%0d pairs), bound %0d; inside regions every %0d..%0d",
                           m0, ep_of(t_w1), plans(m0, ep_of(t_w1)), gx_min, gx_max, gx_n, gr, gl_min, gl_max));
    lgx_max = longint'(gx_max);
    lgx_min = longint'(gx_min);
    lgx_n   = longint'(gx_n);
    if (CNR > 1) begin
      `TB_CHECK(gx_n > 0 && lgx_max <= gr, ("CT05: a cross-region pair waited %0d cycles between turns, bound %0d", gx_max, gr))
      `TB_CHECK(lgx_max == gr && lgx_min == gr,
                ("CT05: cross-region turns %0d..%0d cycles apart, expected exactly one global round at K_MAX, %0d", gx_min, gx_max, gr))
      tb_pkg::cover_bin("CT05 cross-region pairs measured at K_MAX", lgx_n);
    end
    traffic_defaults();
  endtask

  function automatic void ct_summary();
    if (cchk_pkg::the_cchk == null) return;
    tl_summary();
    tb_pkg::info($sformatf("design D run: %0d epochs checked, %0d plan changes, k_L %0d..%0d; every tile had each new plan by cycle %0d (bound %0d); %0d saturated tile sums",
                           cchk_pkg::the_cchk.n_epochs, cchk_pkg::the_cchk.n_changed, cchk_pkg::the_cchk.k_lo,
                           cchk_pkg::the_cchk.k_hi, cchk_pkg::the_cchk.arr_max, sched_ref_pkg::ref_plan_by(MESH_N),
                           cchk_pkg::the_cchk.n_sat));
  endfunction

  /* verilator lint_on UNUSEDSIGNAL */
// ---- end tb/mesh/tests_ctrl.svh
// ---- begin tb/mesh/tests_stress.svh

  task automatic s01();
    int unsigned total, seg, done, len;
    int          k, np;
    bit          ok, ok2;
    real         rf;
    pattern_e    pl [9];
    pl[0] = PAT_UNIFORM;  pl[1] = PAT_TRANSPOSE; pl[2] = PAT_BITCOMP;  pl[3] = PAT_BITROT;  pl[4] = PAT_SHUFFLE;
    pl[5] = PAT_TORNADO;  pl[6] = PAT_NEIGHBOR;  pl[7] = PAT_HOTSPOT;  pl[8] = PAT_REGION;
    np    = 9;
    total = 10000000;
    seg   = 50000;
    if (quick()) begin
      total = 200000;
      seg   = 10000;
    end
    if ($value$plusargs("S01_CYCLES=%d", total)) begin end
    if ($value$plusargs("S01_SEG=%d", seg)) begin end
    if (!$value$plusargs("S01_RATE_FRAC=%f", rf)) rf = 0.5;
    tb_pkg::phase($sformatf("S01: %0d cycles at %0.2f of sat_rate(), pattern switched every %0d cycles", total, rf, seg));
    traffic_defaults();
    traffic_pkg::rate = rf * sat_rate();
    stats_pkg::reset(NN);
    stats_pkg::open_window(cyc + 1, cyc + total + 1);
    traffic_pkg::gen_on = 1'b1;
    ok   = 1'b1;
    done = 0;
    k    = 0;
    while (done < total && ok) begin
      traffic_pkg::pattern = pl[k % np];
      len = seg;
      if (total - done < len) len = total - done;
      u_rc.wait_cycles(len, ok);
      done = done + len;
      k++;
    end
    traffic_pkg::gen_on = 1'b0;
    ok2 = 1'b0;
    if (ok) u_rc.drain(DRAIN_MAX, ok2);
    `TB_CHECK(ok && ok2, ("S01: the mesh stopped delivering after %0d cycles (%0d segments): %s", done, k, why_stuck(0, DRAIN_MAX)))
    stop_if(ok && ok2, "S01");
    report("S01");
    tb_pkg::info($sformatf("S01: %0d segments of %0d cycles, %0d packets delivered, bypass share %0.2f%%",
                           k, seg, stats_pkg::delivered_pkts(), 100.0 * stats_pkg::byp_pkt()));
    tb_pkg::cover_bin("S01 segments", longint'(k));
    check_idle("S01");
    traffic_defaults();
  endtask

  task automatic s02();
    real             lv [4];
    int unsigned     len;
    bit              ok;
    perf_pkg::snap_t pa, pb;
    longint unsigned dec, rcx, acc, trn, cxl;
    real             fa, fb, cr;
    if (DESIGN == DESIGN_A) begin
      tb_pkg::fail("S02 runs on designs B-D (tb_mesh_b, tb_mesh_c, tb_mesh_d)");
      return;
    end
    lv[0] = 0.01; lv[1] = 0.05; lv[2] = 0.10; lv[3] = 0.20;
    len = 20000;
    if (quick()) len = 3000;
    tb_pkg::csv("S02,design,N,V,stall,decisions,accepted,dst_cancels,cancel_rate,turns,src_cancels,lat_avg,pkts");
    for (int i = 0; i < 4; i++) begin
      tb_pkg::phase($sformatf("S02: sinks stall with chance %0.2f per cycle, %0d cycles at half of sat_rate()", lv[i], len));
      traffic_defaults();
      traffic_pkg::rate         = 0.5 * sat_rate();
      traffic_pkg::sink_stall_p = lv[i];
      stats_pkg::reset(NN);
      pa = perf_snap();
      u_rc.run_load(500, len, DRAIN_MAX, ok);
      pb = perf_snap();
      `TB_CHECK(ok, ("S02: stall %0.2f: %s", lv[i], why_stuck(0, DRAIN_MAX)))
      stop_if(ok, "S02");
      dec = pb.dec - pa.dec;
      acc = pb.acc - pa.acc;
      rcx = pb.rcx - pa.rcx;
      trn = pb.turns - pa.turns;
      cxl = pb.cxl - pa.cxl;
      cr  = 0.0;
      fa  = real'(rcx);
      fb  = real'(dec);
      if (dec > 0) cr = fa / fb;
      tb_pkg::csv($sformatf("S02,%s,%0d,%0d,%0.2f,%0d,%0d,%0d,%0.4f,%0d,%0d,%0.3f,%0d", design_name(), MESH_N, NUM_VC, lv[i],
                            dec, acc, rcx, cr, trn, cxl, stats_pkg::lat_avg(), stats_pkg::delivered_pkts()));
      `TB_CHECK(stats_pkg::m_left == 0, ("S02: stall %0.2f: %0d measured packets never delivered", lv[i], stats_pkg::m_left))
      traffic_pkg::sink_stall_p = 0.0;
      check_idle($sformatf("S02 stall %0.2f", lv[i]));
    end
    traffic_defaults();
  endtask

  task automatic s03();
    pattern_e    pl [3];
    int unsigned len;
    bit          ok;
    int          st0;
    if (DESIGN == DESIGN_A || NUM_VC != 1) begin
      tb_pkg::fail("S03 runs on designs B-D with one VC: -define TB_NUM_VC=1 on tb_mesh_b, tb_mesh_c or tb_mesh_d");
      return;
    end
    pl[0] = PAT_UNIFORM; pl[1] = PAT_TRANSPOSE; pl[2] = PAT_HOTSPOT;
    len = 20000;
    if (quick()) len = 4000;
    for (int i = 0; i < 3; i++) begin
      tb_pkg::phase($sformatf("S03: one VC, %s traffic at 0.9 of sat_rate() for %0d cycles", pat_name(pl[i]), len));
      traffic_defaults();
      traffic_pkg::pattern = pl[i];
      traffic_pkg::rate    = 0.9 * sat_rate();
      stats_pkg::reset(NN);
      st0 = u_rc.stalls;
      u_rc.run_load(500, len, DRAIN_MAX, ok);
      `TB_CHECK(ok && u_rc.stalls == st0, ("S03: %s: the watchdog fired or the mesh did not drain: %s", pat_name(pl[i]), why_stuck(st0, DRAIN_MAX)))
      stop_if(ok, "S03");
      report($sformatf("S03 %s", pat_name(pl[i])));
      check_idle($sformatf("S03 %s", pat_name(pl[i])));
    end
    traffic_defaults();
  endtask

  function automatic bit s05_x_flit(flit_t f);
    if ($isunknown(f.vld)) return 1'b1;
    if (f.vld == 1'b1) return $isunknown(f);
    return 1'b0;
  endfunction
  function automatic bit s05_x_cred(credit_t c);
    if ($isunknown(c.vld)) return 1'b1;
    if (c.vld == 1'b1) return $isunknown(c);
    return 1'b0;
  endfunction
  function automatic bit s05_x_la(la_t l);
    if ($isunknown(l.vld)) return 1'b1;
    if (l.vld == 1'b1) return $isunknown(l);
    return 1'b0;
  endfunction
  function automatic bit s05_x_cx(cx_t x);
    if ($isunknown(x.vld)) return 1'b1;
    if (x.vld == 1'b1) return $isunknown(x);
    return 1'b0;
  endfunction

  bit s05_on = 1'b0;
  always @(negedge clk) begin : s05_chk
    flit_t   f;
    credit_t c;
    la_t     l;
    cx_t     x;
    bit      bad_ej, bad_fc, bad_lx;
    if (s05_on) begin
      for (int r = 0; r < NN; r++) begin
        bad_ej = 1'b0;
        if (ej_valid[r] == 1'b1) begin
          f = ej_flit[r];
          if ($isunknown(f)) bad_ej = 1'b1;
        end
        f = ej_mon[r];
        if (s05_x_flit(f)) bad_ej = 1'b1;
        bad_fc = 1'b0;
        bad_lx = 1'b0;
        for (int p = 0; p < 4; p++) begin
          f = dut.t_out_flit[r][p];
          c = dut.t_out_cred[r][p];
          l = dut.t_out_la[r][p];
          x = dut.t_out_cx[r][p];
          if (s05_x_flit(f) || s05_x_cred(c)) bad_fc = 1'b1;
          if (s05_x_la(l) || s05_x_cx(x)) bad_lx = 1'b1;
        end
        `TB_CHECK(!$isunknown(inj_ready[r]) && !$isunknown(ej_valid[r]) && !$isunknown(ej_free[r]),
                  ("S05: cycle %0d: an unknown handshake or free count at NI %0d", cyc, r))
        `TB_CHECK(!bad_ej, ("S05: cycle %0d: an unknown field in a valid flit at NI %0d's outputs", cyc, r))
        `TB_CHECK(!bad_fc, ("S05: cycle %0d: an unknown valid bit, or field of a valid flit or credit, on a link of tile %0d", cyc, r))
        `TB_CHECK(!bad_lx, ("S05: cycle %0d: an unknown valid bit, or field of a valid lookahead or cancel token, on a link of tile %0d", cyc, r))
        `TB_CHECK(!$isunknown(dut.t_sum_o[r]) && !$isunknown(dut.t_plan_o[r]),
                  ("S05: cycle %0d: an unknown demand sum or plan on tile %0d's controller links", cyc, r))
      end
    end
  end

  task automatic s05();
    int unsigned len;
    bit          ok;
    len = 2000;
    if (quick()) len = 1000;
    tb_pkg::phase($sformatf("S05: no X or Z on any link or NI output, %0d cycles of traffic", len));
    traffic_defaults();
    traffic_pkg::rate = 0.5 * sat_rate();
    stats_pkg::reset(NN);
    s05_on = 1'b1;
    u_rc.run_load(200, len, DRAIN_MAX, ok);
    `TB_CHECK(ok, ("S05: %s", why_stuck(0, DRAIN_MAX)))
    stop_if(ok, "S05");
    repeat (20) @(posedge clk);
    s05_on = 1'b0;
    check_idle("S05");
    traffic_defaults();
  endtask
// ---- end tb/mesh/tests_stress.svh

  initial begin
    tb_pkg::start(ID, $sformatf("mesh %0dx%0d, %0d VC, %s routing, %s", MESH_N, MESH_N,
                                NUM_VC, algo_name(), design_name()));
    tb_pkg::rng_init(SID);
    for (int i = 0; i < NN; i++) begin
      tb_pkg::rng_init(100 + i);
      tb_pkg::rng_init(400 + i);
    end
    traffic_defaults();
    repeat (5) @(posedge clk);
    @(negedge clk) rst_n = 1'b1;
    c_rst = cyc;
    @(posedge clk);
    if (DESIGN == DESIGN_C) begin
      if (SHADOW != 0) begin
        if (tb_pkg::test_on("TL05")) tl05();
      end else begin
        if (tb_pkg::test_on("TL01")) tl01();
        if (tb_pkg::test_on("TL02")) tl02();
        if (tb_pkg::test_on("TL03")) tl03();
        if (tb_pkg::test_on("TL04")) tl04();
        if (tb_pkg::test_on("TL06")) tl06();
        if (tb_pkg::sel_test == "N01") n01();
        if (tb_pkg::sel_test == "N03") n03();
        if (tb_pkg::sel_test == "N06") n06();
        if (tb_pkg::sel_test == "N07") n07();
        if (tb_pkg::sel_test == "PERF") perf();
        if (tb_pkg::sel_test == "S01") s01();
        if (tb_pkg::sel_test == "S02") s02();
        if (tb_pkg::sel_test == "S03") s03();
        if (tb_pkg::sel_test == "S05") s05();
      end
      tl_summary();
    end else if (DESIGN == DESIGN_D) begin
      ct_config();
      if (tb_pkg::test_on("CT01")) ct01();
      if (tb_pkg::test_on("CT02")) ct02();
      if (tb_pkg::test_on("CT03")) ct03();
      if (tb_pkg::test_on("CT04")) ct04();
      if (tb_pkg::test_on("CT05")) ct05();
      if (tb_pkg::sel_test == "N01") n01();
      if (tb_pkg::sel_test == "N03") n03();
      if (tb_pkg::sel_test == "N06") n06();
      if (tb_pkg::sel_test == "N07") n07();
      if (tb_pkg::sel_test == "PERF") perf();
      if (tb_pkg::sel_test == "S01") s01();
      if (tb_pkg::sel_test == "S02") s02();
      if (tb_pkg::sel_test == "S03") s03();
      if (tb_pkg::sel_test == "S05") s05();
      ct_summary();
    end else if (DESIGN != DESIGN_A) begin
      if (tb_pkg::test_on("BP01")) bp01();
      if (tb_pkg::test_on("BP02")) bp02();
      if (tb_pkg::test_on("BP03")) bp03();
      if (tb_pkg::test_on("BP04")) bp04();
      if (tb_pkg::test_on("BP05")) bp05();
      if (tb_pkg::test_on("BP06")) bp06();
      if (tb_pkg::test_on("BP07")) bp07();
      if (tb_pkg::test_on("BP09")) bp09();
      if (tb_pkg::test_on("BP10")) bp10();
      if (tb_pkg::sel_test == "BP08") bp08();
      if (tb_pkg::sel_test == "N01") n01();
      if (tb_pkg::sel_test == "N03") n03();
      if (tb_pkg::sel_test == "N06") n06();
      if (tb_pkg::sel_test == "N07") n07();
      if (tb_pkg::sel_test == "PERF") perf();
      if (tb_pkg::sel_test == "S01") s01();
      if (tb_pkg::sel_test == "S02") s02();
      if (tb_pkg::sel_test == "S03") s03();
      if (tb_pkg::sel_test == "S05") s05();
    end else if (ALGO == RT_XY) begin
      if (tb_pkg::test_on("N01")) n01();
      if (tb_pkg::test_on("N02")) n02();
      if (tb_pkg::test_on("N03")) n03();
      if (tb_pkg::test_on("N04")) n04();
      if (tb_pkg::test_on("N06")) n06();
      if (tb_pkg::test_on("N07")) n07();
      if (tb_pkg::test_on("N08")) n08();
      if (tb_pkg::sel_test == "PERF") perf();
      if (tb_pkg::sel_test == "S01") s01();
      if (tb_pkg::sel_test == "S02") s02();
      if (tb_pkg::sel_test == "S03") s03();
      if (tb_pkg::sel_test == "S05") s05();
    end else begin
      if (tb_pkg::test_on("N05")) n05();
      if (tb_pkg::sel_test == "BP08") bp08();
    end
    if ((DESIGN == DESIGN_C || DESIGN == DESIGN_D) && clk === 1'b0) @(posedge clk);
    tb_pkg::info($sformatf("cycles simulated %0d", cyc));
    tb_pkg::finish();
  end

  initial begin
    int unsigned n8, n1;
    string       tn;
    time         t_max;
    if (!$value$plusargs("N08_CYCLES=%d", n8)) n8 = 1000000;
    n1 = 0;
    if ($value$plusargs("TEST=%s", tn)) begin
      if (tn == "S01") begin
        n1 = 10000000;
        if ($value$plusargs("S01_CYCLES=%d", n1)) begin end
      end
    end
    t_max = (time'(n8) + time'(n1) + time'(5000000)) * 10;
    tb_pkg::watchdog(t_max);
  end

endmodule
`endif // NEED_SUPPORT_4

