// =============================================================================
// ==== tb/unit/tb_slot_table.sv   (tests: U05)
// =============================================================================
`ifdef RUN_TB_SLOT_TABLE
// @tests    U05
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module st_tester
  import sched_pkg::*;
#(
  parameter int N = 4
) (
  input  logic go,
  output logic done
);
  localparam int NS = n_slots(N);

  logic    clk   = 1'b0;
  logic    rst_n = 1'b0;
  slot_t   slot  = '0;
  tt_grp_t grp [N];
  logic    act [N];
  tt_grp_t tgt [N];

  always #5 clk = ~clk;

  for (genvar g = 0; g < N; g++) begin : g_dut
    slot_table #(.TT_N(N)) u_dut (
      .clk_i  (clk),
      .rst_ni (rst_n),
      .grp_i  (grp[g]),
      .slot_i (slot),
      .act_o  (act[g]),
      .tgt_o  (tgt[g])
    );
  end

  localparam int TABLE2 [4][4] = '{'{0, 1, 3, 6}, '{1, 2, 4, 7}, '{3, 4, 5, 8}, '{6, 7, 8, 9}};

  int              found [N][N];   // [g][t]: slot where group g was active with target t
  longint unsigned c_act = 0, c_idle = 0, c_same = 0, c_beyond = 0;
  longint unsigned c_tgt [N];
  string           line;

  task automatic do_reset();
    rst_n = 1'b0;
    repeat (2) @(posedge clk);
    #1 rst_n = 1'b1;
    @(negedge clk);
  endtask

  task automatic sweep(int shift);
    int a, b, g_of;
    bit exp_act;
    int exp_tgt;
    for (int v = 0; v < (1 << SLOT_W); v++) begin
      slot = slot_t'(v);
      #1;
      if (v < NS) ref_slot_pair(v, a, b);
      for (int k = 0; k < N; k++) begin
        g_of    = (k + shift) % N;          // the group this table was loaded with
        exp_act = (v < NS) && (g_of == a || g_of == b);
        exp_tgt = (g_of == a) ? b : a;
        `TB_CHECK(act[k] === exp_act,
          ("%0dx%0d table of group %0d, slot %0d: active %b, expected %b", N, N, g_of, v, act[k], exp_act))
        if (exp_act) begin
          `TB_CHECK(int'(tgt[k]) == exp_tgt,
            ("%0dx%0d table of group %0d, slot %0d: target %0d, expected %0d", N, N, g_of, v, tgt[k], exp_tgt))
          if (shift == 0) begin
            found[g_of][int'(tgt[k])] = v;
            c_act++;
            c_tgt[int'(tgt[k])]++;
            if (a == b) c_same++;
          end
        end else if (shift == 0) begin
          if (v < NS) c_idle++;
          else        c_beyond++;
        end
      end
    end
  endtask

  function automatic void ref_slot_pair(int v, output int a, output int b);
    sched_ref_pkg::ref_slot(N, v, a, b);
  endfunction

  initial begin
    done = 1'b0;
    for (int t = 0; t < N; t++) c_tgt[t] = 0;
    for (int g = 0; g < N; g++) for (int t = 0; t < N; t++) found[g][t] = -1;
    for (int k = 0; k < N; k++) grp[k] = tt_grp_t'(k);
    wait (go === 1'b1);
    do_reset();
    sweep(0);

    for (int g = 0; g < N; g++) begin
      for (int t = 0; t < N; t++) begin
        `TB_CHECK(found[g][t] == sched_ref_pkg::ref_table(N, g, t) && found[g][t] == slot_of(g, t),
          ("%0dx%0d group %0d meets group %0d in slot %0d; reference %0d, slot_of %0d", N, N, g, t,
           found[g][t], sched_ref_pkg::ref_table(N, g, t), slot_of(g, t)))
        if (N == 4) begin
          `TB_CHECK(found[g][t] == TABLE2[g][t],
            ("4x4 group %0d meets group %0d in slot %0d; Table II of [1] says %0d", g, t, found[g][t], TABLE2[g][t]))
        end
      end
    end
    if (N == 4) begin
      line = "";
      for (int t = 0; t < N; t++) begin
        if (t != 0) line = {line, ", "};
        line = {line, $sformatf("%0d", found[0][t])};
      end
      tb_pkg::info({"U05 4x4 group 0 table S0..S3 = {", line, "} (Table II of [1]: {0, 1, 3, 6})"});
    end

    for (int k = 0; k < N; k++) grp[k] = tt_grp_t'((k + 1) % N);
    @(negedge clk);
    sweep(0);
    do_reset();
    sweep(1);

    tb_pkg::cover_bin($sformatf("%0dx%0d router active in its slot", N, N), c_act);
    tb_pkg::cover_bin($sformatf("%0dx%0d router idle in another group's slot", N, N), c_idle);
    tb_pkg::cover_bin($sformatf("%0dx%0d same-group slot", N, N), c_same);
    tb_pkg::cover_bin($sformatf("%0dx%0d slot value beyond the round matches nothing", N, N), c_beyond);
    for (int t = 0; t < N; t++)
      tb_pkg::cover_bin($sformatf("%0dx%0d target group %0d", N, N, t), c_tgt[t]);
    done = 1'b1;
  end

endmodule


module tb_slot_table;
  logic       go = 1'b0;
  logic [3:0] done;

  st_tester #(.N(2))  t_2  (.go(go), .done(done[0]));
  st_tester #(.N(4))  t_4  (.go(go), .done(done[1]));
  st_tester #(.N(8))  t_8  (.go(go), .done(done[2]));
  st_tester #(.N(16)) t_16 (.go(go), .done(done[3]));

  `TB_DUMP(tb_slot_table)

  initial tb_pkg::watchdog(100ms);

  initial begin
    tb_pkg::start("U05", "slot_table: lookup tables equal Table II for every group, n = 2, 4, 8, 16");
    go = 1'b1;
    wait (&done === 1'b1);
    tb_pkg::finish();
  end

endmodule
`endif // RUN_TB_SLOT_TABLE

// =============================================================================
// ==== tb/unit/tb_slot_counter.sv   (tests: U06)
// =============================================================================
`ifdef RUN_TB_SLOT_COUNTER
// @tests    U06
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module sc_tester
  import sched_pkg::*;
#(
  parameter int N     = 4,
  parameter int T_SUB = 18,
  parameter int SID   = 100     // random stream of this tester
) (
  input  logic go,
  output logic done
);
  localparam int     S     = s_setup(N);
  localparam int     LEN   = slot_len(N, T_SUB);
  localparam int     NSL   = n_slots(N);
  localparam longint TOTAL = longint'(NSL) * longint'(LEN) + longint'(LEN);

  logic              clk   = 1'b0;
  logic              rst_n = 1'b0;
  logic              en    = 1'b0;
  logic              setup, sub_go, slot_last, nxt_go;
  sub_t              sub, nxt_sub;
  logic [TCYC_W-1:0] cyc;
  slot_t             slot;

  slot_counter #(.TT_N(N), .T_SUB(T_SUB), .S_SETUP(S)) u_dut (
    .clk_i       (clk),
    .rst_ni      (rst_n),
    .en_i        (en),
    .setup_o     (setup),
    .sub_o       (sub),
    .cyc_o       (cyc),
    .slot_o      (slot),
    .sub_go_o    (sub_go),
    .slot_last_o (slot_last),
    .nxt_go_o    (nxt_go),
    .nxt_sub_o   (nxt_sub)
  );

  always #5 clk = ~clk;

  longint          e;      // enabled cycles so far
  longint          total;  // enabled cycles to run
  bit              quick;  // +QUICK
  int              n_ends; // slot ends seen
  int              gap;    // disabled cycles still to come in a forced pause
  int              draw;
  longint unsigned c_wrap = 0, c_gap_end = 0, c_gap_mid = 0, c_nxt_setup = 0, c_nxt_sub = 0, c_last = 0;
  longint unsigned c_sub [N];

  task automatic check_cycle();
    sched_ref_pkg::pos_t p;
    bit                  x_go, x_last, x_nxt;
    p      = sched_ref_pkg::ref_pos(N, T_SUB, S, e);
    x_go   = en && !p.setup && p.cyc == 0;
    x_last = en && !p.setup && p.sub == N - 1 && p.cyc == T_SUB - 1;
    x_nxt  = en && p.cyc == 0 && (p.setup || p.sub < N - 1);
    `TB_CHECK(setup === p.setup && int'(sub) == p.sub && int'(cyc) == p.cyc && int'(slot) == p.slot,
      ("%0dx%0d T=%0d after %0d enabled cycles: setup %b subslot %0d cycle %0d slot %0d, expected %b %0d %0d %0d",
       N, N, T_SUB, e, setup, sub, cyc, slot, p.setup, p.sub, p.cyc, p.slot))
    `TB_CHECK(sub_go === x_go && slot_last === x_last && nxt_go === x_nxt,
      ("%0dx%0d T=%0d after %0d enabled cycles (en %b): sub_go %b slot_last %b nxt_go %b, expected %b %b %b",
       N, N, T_SUB, e, en, sub_go, slot_last, nxt_go, x_go, x_last, x_nxt))
    if (x_nxt) begin
      `TB_CHECK(int'(nxt_sub) == (p.setup ? 0 : p.sub + 1),
        ("%0dx%0d T=%0d after %0d enabled cycles: nxt_sub %0d, expected %0d", N, N, T_SUB, e, nxt_sub,
         p.setup ? 0 : p.sub + 1))
      if (p.setup) c_nxt_setup++;
      else         c_nxt_sub++;
    end
    if (en && !p.setup) c_sub[p.sub]++;
    if (x_last) c_last++;
    if (en && e >= longint'(NSL) * longint'(LEN) && p.slot == 0 && p.setup && p.cyc == 0) c_wrap++;
    if (!en && gap == 0 && p.cyc != 0) c_gap_mid++;
  endtask

  initial begin
    done = 1'b0;
    for (int k = 0; k < N; k++) c_sub[k] = 0;
    wait (go === 1'b1);
    tb_pkg::rng_init(SID);
    repeat (2) @(posedge clk);
    #1 rst_n = 1'b1;
    quick  = $test$plusargs("QUICK");
    total  = (quick && N == 16) ? 4 * longint'(LEN) : TOTAL;
    e      = 0;
    gap    = 0;
    n_ends = 0;
    while (e < total) begin
      @(negedge clk);
      if (gap > 0) begin
        en = 1'b0;
        gap--;
        if (gap == 0) c_gap_end++;
      end else begin
        en = tb_pkg::rng_chance(SID, 0.85);
      end
      #1;
      check_cycle();
      if (en && slot_last) begin
        n_ends++;
        draw = int'(tb_pkg::rng_below(SID, 4));
        if (n_ends == 1 || draw == 0) gap = 1 + int'(tb_pkg::rng_below(SID, 300));
      end
      if (en) e++;
    end
    for (int k = 0; k < N; k++)
      tb_pkg::cover_bin($sformatf("%0dx%0d T=%0d subslot %0d", N, N, T_SUB, k), c_sub[k]);
    if (total == TOTAL) tb_pkg::cover_bin($sformatf("%0dx%0d T=%0d slot number wraps to 0", N, N, T_SUB), c_wrap);
    tb_pkg::cover_bin($sformatf("%0dx%0d T=%0d last cycle of a slot", N, N, T_SUB), c_last);
    tb_pkg::cover_bin($sformatf("%0dx%0d T=%0d pause at a slot boundary", N, N, T_SUB), c_gap_end);
    tb_pkg::cover_bin($sformatf("%0dx%0d T=%0d pause inside a setup window or subslot", N, N, T_SUB), c_gap_mid);
    tb_pkg::cover_bin($sformatf("%0dx%0d T=%0d cancel decision in the setup window", N, N, T_SUB), c_nxt_setup);
    tb_pkg::cover_bin($sformatf("%0dx%0d T=%0d cancel decision in a subslot", N, N, T_SUB), c_nxt_sub);
    done = 1'b1;
  end

endmodule


module tb_slot_counter;
  import sched_pkg::*;

  logic       go = 1'b0;
  logic [8:0] done;

  sc_tester #(.N(2),  .T_SUB(t_tight(2, 10)),  .SID(100)) t_2   (.go(go), .done(done[0]));
  sc_tester #(.N(4),  .T_SUB(t_tight(4, 10)),  .SID(101)) t_4t  (.go(go), .done(done[1]));
  sc_tester #(.N(4),  .T_SUB(t_safe(4, 10)),   .SID(102)) t_4s  (.go(go), .done(done[2]));
  sc_tester #(.N(4),  .T_SUB(t_tight(4, 5)),   .SID(103)) t_4b5 (.go(go), .done(done[3]));
  sc_tester #(.N(4),  .T_SUB(hmax(4) + 1),     .SID(104)) t_4m  (.go(go), .done(done[4]));
  sc_tester #(.N(8),  .T_SUB(t_tight(8, 10)),  .SID(105)) t_8t  (.go(go), .done(done[5]));
  sc_tester #(.N(8),  .T_SUB(t_safe(8, 15)),   .SID(106)) t_8s  (.go(go), .done(done[6]));
  sc_tester #(.N(16), .T_SUB(t_tight(16, 10)), .SID(107)) t_16t (.go(go), .done(done[7]));
  sc_tester #(.N(16), .T_SUB(t_safe(16, 10)),  .SID(108)) t_16s (.go(go), .done(done[8]));

  `TB_DUMP(tb_slot_counter)

  initial tb_pkg::watchdog(100ms);

  initial begin
    tb_pkg::start("U06", "slot_counter: setup, subslots, cycles, slot number and enable equal the reference every cycle");
    go = 1'b1;
    wait (&done === 1'b1);
    tb_pkg::info("U06 counters: 2x2 T=10; 4x4 T=18, 24, 13, 7; 8x8 T=34, 45; 16x16 T=66, 72 (one round plus one slot each)");
    tb_pkg::finish();
  end

endmodule
`endif // RUN_TB_SLOT_COUNTER

// =============================================================================
// ==== tb/unit/tb_group_to_router.sv   (tests: U07)
// =============================================================================
`ifdef RUN_TB_GROUP_TO_ROUTER
// @tests    U07
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module gr_tester
  import noc_pkg::*;
  import sched_pkg::*;
#(
  parameter int MESH = 4,     // mesh side
  parameter int TT   = 4      // timetable side (TT < MESH: local, regions of TT x TT)
) (
  input  logic go,
  output logic done
);
  localparam int NR = MESH * MESH;
  localparam int NS = n_slots(TT);

  coord_t  x = '0, y = '0;
  logic    act = 1'b0;
  tt_grp_t tgt = '0;
  sub_t    sub = '0;
  logic    tx_vld, rx_vld, tx_mode, rx_mode;
  coord_t  tx_x, tx_y, rx_x, rx_y;
  hop_t    tx_hops, rx_hops;

  group_to_router #(.MESH_N(MESH), .TT_N(TT)) u_dut (
    .x_i       (x),
    .y_i       (y),
    .act_i     (act),
    .tgt_i     (tgt),
    .sub_i     (sub),
    .tx_vld_o  (tx_vld),
    .tx_x_o    (tx_x),
    .tx_y_o    (tx_y),
    .tx_mode_o (tx_mode),
    .tx_hops_o (tx_hops),
    .rx_vld_o  (rx_vld),
    .rx_x_o    (rx_x),
    .rx_y_o    (rx_y),
    .rx_mode_o (rx_mode),
    .rx_hops_o (rx_hops)
  );

  localparam int FIG3 [4][4][2] = '{
    '{'{2, 3},  '{7, 4},  '{8, 9},   '{13, 14}},
    '{'{2, 14}, '{7, 3},  '{8, 4},   '{13, 9}},
    '{'{2, 9},  '{7, 14}, '{8, 3},   '{13, 4}},
    '{'{2, 4},  '{7, 9},  '{8, 14},  '{13, 3}}};

  bit  d_tx_v [NR], d_rx_v [NR], d_tx_m [NR], d_rx_m [NR];
  int  d_tx [NR], d_rx [NR], d_tx_h [NR], d_rx_h [NR];
  int  e_tx [NR], e_rx [NR];
  bit  e_tx_m [NR], e_rx_m [NR];

  longint unsigned c_tx = 0, c_rx = 0, c_idle_same = 0, c_inactive = 0, c_xy = 0, c_yx = 0, c_fig3 = 0;
  int              max_hops = 0;

  function automatic int iabs(int v);
    return (v < 0) ? -v : v;
  endfunction

  task automatic build_ref(int slot, int s);
    sched_ref_pkg::xfer_q_t q;
    int                     src, dst;
    for (int r = 0; r < NR; r++) begin
      e_tx[r] = -1;
      e_rx[r] = -1;
      e_tx_m[r] = 1'b0;
      e_rx_m[r] = 1'b0;
    end
    q = sched_ref_pkg::ref_xfers(TT, slot, s, 1'b0);
    for (int by = 0; by < MESH; by += TT) begin
      for (int bx = 0; bx < MESH; bx += TT) begin
        foreach (q[i]) begin
          src = (by + q[i].sy) * MESH + bx + q[i].sx;
          dst = (by + q[i].dy) * MESH + bx + q[i].dx;
          if (e_tx[src] != -1 || e_rx[dst] != -1)
            tb_pkg::fail($sformatf("reference: router %0d or %0d used twice in slot %0d subslot %0d", src, dst, slot, s));
          e_tx[src]   = dst;
          e_tx_m[src] = q[i].mode;
          e_rx[dst]   = src;
          e_rx_m[dst] = q[i].mode;
        end
      end
    end
  endtask

  task automatic probe(int r, int slot, int s);
    int  a, b, g, txi, rxi, exp_h;
    bit  in_slot;
    x = coord_t'(r % MESH);
    y = coord_t'(r / MESH);
    sched_ref_pkg::ref_slot(TT, slot, a, b);
    g       = sched_ref_pkg::ref_group(r % MESH % TT, r / MESH % TT, TT);
    in_slot = (g == a || g == b);
    act     = in_slot;
    tgt     = tt_grp_t'((g == a) ? b : a);
    sub     = sub_t'(s);
    #1;
    d_tx_v[r] = tx_vld;
    d_rx_v[r] = rx_vld;
    d_tx_m[r] = tx_mode;
    d_rx_m[r] = rx_mode;
    d_tx[r]   = int'(tx_y) * MESH + int'(tx_x);
    d_rx[r]   = int'(rx_y) * MESH + int'(rx_x);
    d_tx_h[r] = int'(tx_hops);
    d_rx_h[r] = int'(rx_hops);
    txi = e_tx[r];
    rxi = e_rx[r];
    `TB_CHECK(tx_vld === (txi != -1) && rx_vld === (rxi != -1),
      ("%0dx%0d/%0d router %0d slot %0d subslot %0d: tx_vld %b rx_vld %b, expected %b %b", MESH, MESH, TT, r, slot, s,
       tx_vld, rx_vld, txi != -1, rxi != -1))
    if (txi != -1) begin
      exp_h = iabs(txi % MESH - r % MESH) + iabs(txi / MESH - r / MESH);
      `TB_CHECK(d_tx[r] == txi && tx_mode === e_tx_m[r] && int'(tx_hops) == exp_h,
        ("%0dx%0d/%0d router %0d slot %0d subslot %0d: sends to %0d mode %b in %0d hops, expected %0d mode %b in %0d",
         MESH, MESH, TT, r, slot, s, d_tx[r], tx_mode, tx_hops, txi, e_tx_m[r], exp_h))
      c_tx++;
      if (tx_mode == MODE_XY) c_xy++;
      else                    c_yx++;
      if (exp_h > max_hops) max_hops = exp_h;
    end else begin
      `TB_CHECK(tx_x == '0 && tx_y == '0 && tx_mode == 1'b0 && tx_hops == '0,
        ("%0dx%0d/%0d router %0d slot %0d subslot %0d: tx fields not zero while tx_vld is 0", MESH, MESH, TT, r, slot, s))
    end
    if (rxi != -1) begin
      exp_h = iabs(rxi % MESH - r % MESH) + iabs(rxi / MESH - r / MESH);
      `TB_CHECK(d_rx[r] == rxi && rx_mode === e_rx_m[r] && int'(rx_hops) == exp_h,
        ("%0dx%0d/%0d router %0d slot %0d subslot %0d: receives from %0d mode %b in %0d hops, expected %0d mode %b in %0d",
         MESH, MESH, TT, r, slot, s, d_rx[r], rx_mode, rx_hops, rxi, e_rx_m[r], exp_h))
      c_rx++;
    end else begin
      `TB_CHECK(rx_x == '0 && rx_y == '0 && rx_mode == 1'b0 && rx_hops == '0,
        ("%0dx%0d/%0d router %0d slot %0d subslot %0d: rx fields not zero while rx_vld is 0", MESH, MESH, TT, r, slot, s))
    end
    if (in_slot && a == b && s == 0) c_idle_same++;
    if (in_slot) begin
      act = 1'b0;
      #1;
      `TB_CHECK(!tx_vld && !rx_vld && tx_x == '0 && tx_y == '0 && rx_x == '0 && rx_y == '0 && tx_hops == '0 && rx_hops == '0,
        ("%0dx%0d/%0d router %0d slot %0d subslot %0d: outputs not idle with act_i = 0", MESH, MESH, TT, r, slot, s))
      c_inactive++;
    end
  endtask

  task automatic cross_check(int slot, int s);
    for (int r = 0; r < NR; r++) begin
      if (d_tx_v[r]) begin
        `TB_CHECK(d_tx[r] >= 0 && d_tx[r] < NR && d_tx[r] != r && d_rx_v[d_tx[r]] && d_rx[d_tx[r]] == r &&
                  d_rx_m[d_tx[r]] == d_tx_m[r] && d_rx_h[d_tx[r]] == d_tx_h[r],
          ("%0dx%0d/%0d slot %0d subslot %0d: %0d sends to %0d, which does not receive from it in the same mode and hops",
           MESH, MESH, TT, slot, s, r, d_tx[r]))
      end
      if (d_rx_v[r]) begin
        `TB_CHECK(d_rx[r] >= 0 && d_rx[r] < NR && d_tx_v[d_rx[r]] && d_tx[d_rx[r]] == r,
          ("%0dx%0d/%0d slot %0d subslot %0d: %0d receives from %0d, which does not send to it",
           MESH, MESH, TT, slot, s, r, d_rx[r]))
      end
    end
  endtask

  task automatic check_fig3(int s);
    int lo, hi;
    for (int k = 0; k < 4; k++) begin
      lo = FIG3[s][k][0];
      hi = FIG3[s][k][1];
      `TB_CHECK(d_tx_v[lo] && d_tx[lo] == hi && d_tx_v[hi] && d_tx[hi] == lo && d_tx_m[lo] == MODE_XY && d_tx_m[hi] == MODE_YX,
        ("Fig. 3, slot 8 subslot %0d: R%0d and R%0d should swap bursts (XY up, YX down); R%0d sends to %0d, R%0d to %0d",
         s, lo, hi, lo, d_tx[lo], hi, d_tx[hi]))
      c_fig3++;
    end
  endtask

  int n_run;   // slots checked

  initial begin
    done  = 1'b0;
    n_run = NS;
    if ($test$plusargs("QUICK") && TT == 16) n_run = 16;
    if ($test$plusargs("QUICK") && TT == 8 && MESH == 16) n_run = 10;
    wait (go === 1'b1);
    for (int slot = 0; slot < n_run; slot++) begin
      for (int s = 0; s < TT; s++) begin
        build_ref(slot, s);
        for (int r = 0; r < NR; r++) probe(r, slot, s);
        cross_check(slot, s);
        if (MESH == 4 && TT == 4 && slot == 8) check_fig3(s);
      end
    end
    if (MESH == 4 && TT == 4) begin
      tb_pkg::info("U07 4x4 slot 8 reproduces Fig. 3 of [1]: subslot 0 R2-R3 R7-R4 R8-R9 R13-R14, subslot 1 R2-R14 R7-R3 R8-R4 R13-R9,");
      tb_pkg::info("    subslot 2 R2-R9 R7-R14 R8-R3 R13-R4, subslot 3 R2-R4 R7-R9 R8-R14 R13-R3");
      tb_pkg::cover_bin("4x4 Fig. 3 pairs checked", c_fig3);
    end
    tb_pkg::cover_bin($sformatf("%0dx%0d/%0d router sends", MESH, MESH, TT), c_tx);
    tb_pkg::cover_bin($sformatf("%0dx%0d/%0d router receives", MESH, MESH, TT), c_rx);
    tb_pkg::cover_bin($sformatf("%0dx%0d/%0d path by XY", MESH, MESH, TT), c_xy);
    tb_pkg::cover_bin($sformatf("%0dx%0d/%0d path by YX", MESH, MESH, TT), c_yx);
    tb_pkg::cover_bin($sformatf("%0dx%0d/%0d idle in subslot 0 of a same-group slot", MESH, MESH, TT), c_idle_same);
    tb_pkg::cover_bin($sformatf("%0dx%0d/%0d router not active", MESH, MESH, TT), c_inactive);
    tb_pkg::cover_bin($sformatf("%0dx%0d/%0d longest path, Hmax = %0d hops", MESH, MESH, TT, hmax(TT)),
                      (max_hops == hmax(TT)) ? 1 : 0);
    done = 1'b1;
  end

endmodule


module tb_group_to_router;
  logic       go = 1'b0;
  logic [8:0] done;

  gr_tester #(.MESH(2),  .TT(2))  t_2    (.go(go), .done(done[0]));
  gr_tester #(.MESH(4),  .TT(4))  t_4    (.go(go), .done(done[1]));
  gr_tester #(.MESH(8),  .TT(8))  t_8    (.go(go), .done(done[2]));
  gr_tester #(.MESH(16), .TT(16)) t_16   (.go(go), .done(done[3]));
  gr_tester #(.MESH(8),  .TT(4))  t_8r4  (.go(go), .done(done[4]));
  gr_tester #(.MESH(16), .TT(4))  t_16r4 (.go(go), .done(done[5]));
  gr_tester #(.MESH(8),  .TT(2))  t_8r2  (.go(go), .done(done[6]));
  gr_tester #(.MESH(16), .TT(2))  t_16r2 (.go(go), .done(done[7]));
  gr_tester #(.MESH(16), .TT(8))  t_16r8 (.go(go), .done(done[8]));

  `TB_DUMP(tb_group_to_router)

  initial tb_pkg::watchdog(100ms);

  initial begin
    tb_pkg::start("U07", "group_to_router: partners follow Eq. (2) and D37, tx and rx agree, Fig. 3 reproduced");
    go = 1'b1;
    wait (&done === 1'b1);
    tb_pkg::finish();
  end

endmodule
`endif // RUN_TB_GROUP_TO_ROUTER
